BEGIN;

-- Карты таро (78): тексты на двух языках, ключевые слова, толкования
UPDATE tarot_cards SET slug = 'the-fool', name_en = 'The Fool', keywords_ru = ARRAY['начала', 'невинность', 'спонтанность', 'прыжок веры']::text[], keywords_en = ARRAY['beginnings', 'innocence', 'spontaneity', 'leap of faith']::text[], description_ru = 'Путник делает шаг к краю обрыва, глядя в небо — лёгкий и бесстрашный перед тем, что ждёт впереди.', description_en = 'A traveler steps toward a cliff''s edge, gazing skyward, unburdened and unafraid of what comes next.', meaning_upright = 'Новое начало с открытым сердцем — этот расклад может говорить о том, что пора сделать шаг, даже если ответы найдены не на все вопросы.', meaning_reversed = 'Колебания, безрассудство или шаг без какой-либо подготовки — баланс между смелостью и осторожностью сейчас может быть нарушен.', meaning_upright_en = 'A fresh start with an open heart — this reading may suggest it''s time to take the leap, even without every answer in hand.', meaning_reversed_en = 'Hesitation, recklessness, or a step taken without any preparation at all — the balance between courage and care may be off right now.', meanings_ru = '{"upright":"Новое начало с открытым сердцем — этот расклад может говорить о том, что пора сделать шаг, даже если ответы найдены не на все вопросы.","reversed":"Колебания, безрассудство или шаг без какой-либо подготовки — баланс между смелостью и осторожностью сейчас может быть нарушен.","love":"Новая связь или отношения, вступающие в более лёгкую, спонтанную главу.","career":"Нестандартная возможность или первый шаг на незнакомую профессиональную территорию.","finance":"Готовность рискнуть — стоит сочетать её хотя бы с небольшой осторожностью.","spiritual":"Доверие к неизвестному; символически эта карта может означать душу в самом начале пути."}'::jsonb, meanings_en = '{"upright":"A fresh start with an open heart — this reading may suggest it''s time to take the leap, even without every answer in hand.","reversed":"Hesitation, recklessness, or a step taken without any preparation at all — the balance between courage and care may be off right now.","love":"A new connection or a relationship entering a lighter, more spontaneous chapter.","career":"An unconventional opportunity or a first step into unfamiliar professional territory.","finance":"A willingness to take a chance — worth pairing with at least a little caution.","spiritual":"Trust in the unknown; symbolically, this card can represent the soul at the very start of its journey."}'::jsonb, yes_no = 'yes-if-cautious' WHERE id = 1 AND num = 0;
UPDATE tarot_cards SET slug = 'the-magician', name_en = 'The Magician', keywords_ru = ARRAY['воплощение', 'сила воли', 'находчивость', 'действие']::text[], keywords_en = ARRAY['manifestation', 'willpower', 'resourcefulness', 'action']::text[], description_ru = 'Одна рука указывает в небо, другая — на землю, а на столе перед фигурой разложены инструменты всех четырёх мастей.', description_en = 'One hand points to the sky, the other to the earth, with every tool of the suits laid out on the table before them.', meaning_upright = 'Одна из возможных трактовок: у вас уже есть все нужные инструменты — это может быть момент действовать, а не ждать.', meaning_reversed = 'Рассеянная энергия, нераскрытый потенциал или разрыв между талантом и доведением дела до конца.', meaning_upright_en = 'One possible interpretation is that you already hold every tool you need — this can be a moment to act, not wait.', meaning_reversed_en = 'Scattered energy, untapped potential, or a gap between talent and follow-through.', meanings_ru = '{"upright":"Одна из возможных трактовок: у вас уже есть все нужные инструменты — это может быть момент действовать, а не ждать.","reversed":"Рассеянная энергия, нераскрытый потенциал или разрыв между талантом и доведением дела до конца.","love":"Осознанная, намеренная связь — ясный разговор о том, чего вы хотите.","career":"Момент настоящей самостоятельности: навыки и ресурсы выстроены так, чтобы что-то произошло.","finance":"Находчивость окупается, если намерения остаются честными, а не манипулятивными.","spiritual":"Точка, где внутренняя воля встречается с внешним миром, — символически искра самого творения."}'::jsonb, meanings_en = '{"upright":"One possible interpretation is that you already hold every tool you need — this can be a moment to act, not wait.","reversed":"Scattered energy, untapped potential, or a gap between talent and follow-through.","love":"Conscious, intentional connection — communicating clearly about what you want.","career":"A moment of real agency; skills and resources are aligned to make something happen.","finance":"Resourcefulness pays off, provided intention stays honest rather than manipulative.","spiritual":"The point where inner will meets outer world — symbolically, the spark of creation itself."}'::jsonb, yes_no = 'yes' WHERE id = 2 AND num = 1;
UPDATE tarot_cards SET slug = 'the-high-priestess', name_en = 'The High Priestess', keywords_ru = ARRAY['интуиция', 'тайна', 'подсознание', 'тишина']::text[], keywords_en = ARRAY['intuition', 'mystery', 'the subconscious', 'stillness']::text[], description_ru = 'Восседая между двумя колоннами света и тени, она хранит завесу с вышитыми гранатами — знание, ещё не готовое быть произнесённым.', description_en = 'Seated between two pillars of light and shadow, she guards a veil embroidered with pomegranates — knowledge not yet ready to be spoken.', meaning_upright = 'Этот расклад может подсказывать: прислушайтесь к себе, прежде чем спрашивать других, — интуиция, возможно, уже знает ответ.', meaning_reversed = 'Потеря связи с интуицией, слишком долго хранимые секреты или утаиваемая информация.', meaning_upright_en = 'This reading may suggest listening inward before asking anyone else — intuition may already know the answer.', meaning_reversed_en = 'Disconnection from intuition, secrets kept too long, or information being withheld.', meanings_ru = '{"upright":"Этот расклад может подсказывать: прислушайтесь к себе, прежде чем спрашивать других, — интуиция, возможно, уже знает ответ.","reversed":"Потеря связи с интуицией, слишком долго хранимые секреты или утаиваемая информация.","love":"Невысказанные чувства; связь, в которой есть подводное течение несказанного.","career":"Доверьтесь предчувствию, но тихо проверьте его, прежде чем действовать открыто.","finance":"Ситуация, ещё не полностью видимая, — терпение перед принятием обязательств может пойти на пользу.","spiritual":"Порог между сознанием и подсознанием; символически — священное внутреннее знание."}'::jsonb, meanings_en = '{"upright":"This reading may suggest listening inward before asking anyone else — intuition may already know the answer.","reversed":"Disconnection from intuition, secrets kept too long, or information being withheld.","love":"Feelings not yet spoken aloud; a connection with an undercurrent of the unsaid.","career":"Trust a hunch, but verify quietly before acting on it publicly.","finance":"A situation not fully visible yet — patience before committing may serve well.","spiritual":"The threshold between the conscious and subconscious mind; symbolically, sacred inner knowing."}'::jsonb, yes_no = 'maybe' WHERE id = 3 AND num = 2;
UPDATE tarot_cards SET slug = 'the-empress', name_en = 'The Empress', keywords_ru = ARRAY['изобилие', 'забота', 'творчество', 'природа']::text[], keywords_en = ARRAY['abundance', 'nurturing', 'creativity', 'nature']::text[], description_ru = 'Она покоится на пышном поле под звёздным пологом, увенчанная колосьями и изобилием, — воплощение роста в полном расцвете.', description_en = 'Resting in a lush field beneath a canopy of stars, crowned with grain and comfort, she embodies growth in full bloom.', meaning_upright = 'Изобилие, творчество и забота, приходящие к плодам, — время, когда вложения в проект, отношения или в себя окупаются.', meaning_reversed = 'Творческий блок, пренебрежение собой или забота, переросшая в контроль.', meaning_upright_en = 'Abundance, creativity, and care coming to fruition — a season where nurturing something (a project, a relationship, yourself) pays off.', meaning_reversed_en = 'Creative block, self-neglect, or smothering care that has tipped into control.', meanings_ru = '{"upright":"Изобилие, творчество и забота, приходящие к плодам, — время, когда вложения в проект, отношения или в себя окупаются.","reversed":"Творческий блок, пренебрежение собой или забота, переросшая в контроль.","love":"Тепло, чувственность и заботливая нежность; возможно, период роста в отношениях.","career":"Творческая работа процветает; хороший период, чтобы строить, а не разрушать.","finance":"Материальный комфорт и устойчивый рост, хотя, возможно, через излишества, за которыми стоит следить.","spiritual":"Символически — плодородная, порождающая сила самой природы: творчество как преданность."}'::jsonb, meanings_en = '{"upright":"Abundance, creativity, and care coming to fruition — a season where nurturing something (a project, a relationship, yourself) pays off.","reversed":"Creative block, self-neglect, or smothering care that has tipped into control.","love":"Warmth, sensuality, and nurturing affection; possibly a season of growth in a relationship.","career":"Creative work flourishes; a good period for building rather than tearing down.","finance":"Material comfort and steady growth, though possibly through indulgence worth watching.","spiritual":"Symbolically, the fertile, generative force of nature itself — creation as devotion."}'::jsonb, yes_no = 'yes' WHERE id = 4 AND num = 3;
UPDATE tarot_cards SET slug = 'the-emperor', name_en = 'The Emperor', keywords_ru = ARRAY['структура', 'власть', 'стабильность', 'дисциплина']::text[], keywords_en = ARRAY['structure', 'authority', 'stability', 'discipline']::text[], description_ru = 'Восседая на троне из камня с резными бараньими головами, в доспехах под мантией, он правит порядком, а не порывом.', description_en = 'Enthroned on stone carved with rams'' heads, armor beneath his robe, he rules through order rather than impulse.', meaning_upright = 'Структура и дисциплина могут быть именно тем, что нужно, — это может быть карта устойчивой, заслуженной власти.', meaning_reversed = 'Жёсткость, контроль ради контроля или структура, ставшая клеткой, а не опорой.', meaning_upright_en = 'Structure and discipline may be exactly what''s needed — this can be a card of steady, earned authority.', meaning_reversed_en = 'Rigidity, control for its own sake, or structure that has become a cage rather than a support.', meanings_ru = '{"upright":"Структура и дисциплина могут быть именно тем, что нужно, — это может быть карта устойчивой, заслуженной власти.","reversed":"Жёсткость, контроль ради контроля или структура, ставшая клеткой, а не опорой.","love":"Отношениям может помочь чёткость границ или обязательств — либо партнёр, который ведёт за собой стабильностью.","career":"Лидерство, структура или шаг к большей ответственности.","finance":"Дисциплина и планирование сейчас, скорее всего, полезнее импровизации.","spiritual":"Символически — порядок, наведённый над хаосом: каркас, позволяющий росту стоять прямо."}'::jsonb, meanings_en = '{"upright":"Structure and discipline may be exactly what''s needed — this can be a card of steady, earned authority.","reversed":"Rigidity, control for its own sake, or structure that has become a cage rather than a support.","love":"A relationship benefiting from clearer boundaries or commitment, or a partner who leads with stability.","career":"Leadership, structure, or a step into greater responsibility.","finance":"Discipline and planning likely serve better right now than improvisation.","spiritual":"Symbolically, order imposed on chaos — the architecture that lets growth stand upright."}'::jsonb, yes_no = 'yes' WHERE id = 5 AND num = 4;
UPDATE tarot_cards SET slug = 'the-hierophant', name_en = 'The Hierophant', keywords_ru = ARRAY['традиция', 'системы верований', 'наставничество', 'конформизм']::text[], keywords_en = ARRAY['tradition', 'belief systems', 'mentorship', 'conformity']::text[], description_ru = 'Сидя между двумя колоннами, у его ног скрещены два ключа — он мост между священным и повседневным.', description_en = 'Seated between two pillars, two keys crossed at his feet, he is a bridge between the sacred and the everyday.', meaning_upright = 'Руководство через традицию, наставничество или проверенный путь — возможно, сейчас структура и общая мудрость помогут больше, чем путь в одиночку.', meaning_reversed = 'Сомнение в унаследованных убеждениях или ощущение, что вас зажимают институт, традиция или чужие ожидания.', meaning_upright_en = 'Guidance through tradition, mentorship, or an established path — this may be a moment where structure and shared wisdom help more than going it alone.', meaning_reversed_en = 'Questioning inherited beliefs, or feeling boxed in by an institution, tradition, or others'' expectations.', meanings_ru = '{"upright":"Руководство через традицию, наставничество или проверенный путь — возможно, сейчас структура и общая мудрость помогут больше, чем путь в одиночку.","reversed":"Сомнение в унаследованных убеждениях или ощущение, что вас зажимают институт, традиция или чужие ожидания.","love":"Традиционная веха в отношениях или проясняющиеся ценности, связанные с обязательствами.","career":"Наставничество, формальное обучение или успешная работа внутри устоявшейся системы.","finance":"Привычные, проверенные подходы здесь, скорее всего, сработают лучше импровизации.","spiritual":"Символически — сосуд, хранящий традицию: ритуал, учение, общий смысл."}'::jsonb, meanings_en = '{"upright":"Guidance through tradition, mentorship, or an established path — this may be a moment where structure and shared wisdom help more than going it alone.","reversed":"Questioning inherited beliefs, or feeling boxed in by an institution, tradition, or others'' expectations.","love":"A conventional relationship milestone, or values around commitment coming into focus.","career":"Mentorship, formal training, or working well within an established system.","finance":"Conventional, well-tested approaches likely outperform improvisation here.","spiritual":"Symbolically, the container that holds a tradition — ritual, teaching, shared meaning."}'::jsonb, yes_no = 'maybe' WHERE id = 6 AND num = 5;
UPDATE tarot_cards SET slug = 'the-lovers', name_en = 'The Lovers', keywords_ru = ARRAY['связь', 'ценности', 'выбор', 'согласованность']::text[], keywords_en = ARRAY['connection', 'values', 'choice', 'alignment']::text[], description_ru = 'Две фигуры стоят под взглядом ангела, а позади них пылает солнце — союз, засвидетельствованный свыше, и свободно сделанный выбор.', description_en = 'Two figures stand beneath a watching angel, a sun blazing behind them — union witnessed, and a choice freely made.', meaning_upright = 'Значимая связь или выбор, который просит действовать из ваших настоящих ценностей, а не под внешним давлением.', meaning_reversed = 'Рассогласованность, конфликт ценностей или отношения вне равновесия.', meaning_upright_en = 'A meaningful connection, or a choice that asks you to act from your real values rather than pressure from outside.', meaning_reversed_en = 'Misalignment, a values conflict, or a relationship out of balance.', meanings_ru = '{"upright":"Значимая связь или выбор, который просит действовать из ваших настоящих ценностей, а не под внешним давлением.","reversed":"Рассогласованность, конфликт ценностей или отношения вне равновесия.","love":"Глубокая связь, совпадающая по ценностям, — или развилка, о которой этот расклад, возможно, предлагает честно сказать вслух.","career":"Выбор между путями; подумайте, какой из них действительно отражает то, что вам важно.","finance":"Решение, которое лучше принимать вместе или исходя из ценностей, а не из давления.","spiritual":"Символически — союз взаимодополняющих сил: выбор как акт целостности."}'::jsonb, meanings_en = '{"upright":"A meaningful connection, or a choice that asks you to act from your real values rather than pressure from outside.","reversed":"Misalignment, a values conflict, or a relationship out of balance.","love":"A deep, values-aligned connection — or a fork in the road that this reading may suggest is worth naming honestly.","career":"A choice between paths; consider which one actually reflects what you value.","finance":"A decision best made jointly, or one that should follow your values rather than pressure.","spiritual":"Symbolically, the union of complementary forces — choice as an act of integrity."}'::jsonb, yes_no = 'yes' WHERE id = 7 AND num = 6;
UPDATE tarot_cards SET slug = 'the-chariot', name_en = 'The Chariot', keywords_ru = ARRAY['сила воли', 'импульс', 'фокус', 'контроль']::text[], keywords_en = ARRAY['willpower', 'momentum', 'focus', 'control']::text[], description_ru = 'Фигура в доспехах выезжает вперёд, держа поводья, и одной лишь силой воли направляет двух противоборствующих сфинксов.', description_en = 'A figure rides out in armor, reins in hand, driving two opposing sphinxes forward through sheer force of will.', meaning_upright = 'Решимость и сфокусированная воля, дающие настоящий импульс, — противоборствующие силы удержаны вместе и направлены в одну сторону.', meaning_reversed = 'Потеря направления или воля, растрачиваемая на внутренний конфликт вместо движения вперёд.', meaning_upright_en = 'Determination and focused will driving real momentum — opposing forces held together and pointed in one direction.', meaning_reversed_en = 'Loss of direction, or willpower spent fighting internal conflict instead of moving forward.', meanings_ru = '{"upright":"Решимость и сфокусированная воля, дающие настоящий импульс, — противоборствующие силы удержаны вместе и направлены в одну сторону.","reversed":"Потеря направления или воля, растрачиваемая на внутренний конфликт вместо движения вперёд.","love":"Целеустремлённое движение к отношениям или поиск выхода из противоречивых чувств.","career":"Амбиции и фокус двигают проект или цель вперёд — при условии, что направление действительно верное.","finance":"Дисциплина и напор могут дать здесь реальный прогресс.","spiritual":"Символически — воля, направляющая противоположные внутренние силы к единой цели."}'::jsonb, meanings_en = '{"upright":"Determination and focused will driving real momentum — opposing forces held together and pointed in one direction.","reversed":"Loss of direction, or willpower spent fighting internal conflict instead of moving forward.","love":"Pursuing a relationship with real intention, or navigating conflicting feelings toward a decision.","career":"Ambition and focus pushing a project or goal forward, provided the direction is actually right.","finance":"Discipline and drive can produce real progress here.","spiritual":"Symbolically, the will directing opposing inner forces toward a single purpose."}'::jsonb, yes_no = 'yes' WHERE id = 8 AND num = 7;
UPDATE tarot_cards SET slug = 'strength', name_en = 'Strength', keywords_ru = ARRAY['мужество', 'сострадание', 'внутренняя решимость', 'терпение']::text[], keywords_en = ARRAY['courage', 'compassion', 'inner resolve', 'patience']::text[], description_ru = 'Фигура спокойно смыкает пасть льва голыми руками — не силой, а тихим, терпеливым мужеством.', description_en = 'A figure calmly closes a lion''s jaw with bare hands — not through force, but through quiet, patient courage.', meaning_upright = 'Мягкая сила и терпение побеждают там, где сила не справилась бы, — этот расклад может указывать на мужество, растущее из сострадания, а не из подавления.', meaning_reversed = 'Сомнения в себе или сила, обращающаяся в жёсткость либо срыв под давлением.', meaning_upright_en = 'Gentle strength and patience succeed where force would fail — this reading may point to courage that comes from compassion, not domination.', meaning_reversed_en = 'Self-doubt, or strength turning into either harshness or collapse under pressure.', meanings_ru = '{"upright":"Мягкая сила и терпение побеждают там, где сила не справилась бы, — этот расклад может указывать на мужество, растущее из сострадания, а не из подавления.","reversed":"Сомнения в себе или сила, обращающаяся в жёсткость либо срыв под давлением.","love":"Терпение и мягкость помогают отношениям выстоять в трудный момент.","career":"Тихая настойчивость и самообладание под давлением сейчас эффективнее агрессии.","finance":"Сдержанность и ровные нервы служат лучше резкого, импульсивного шага.","spiritual":"Символически — приручение инстинкта состраданием, а не подавлением."}'::jsonb, meanings_en = '{"upright":"Gentle strength and patience succeed where force would fail — this reading may point to courage that comes from compassion, not domination.","reversed":"Self-doubt, or strength turning into either harshness or collapse under pressure.","love":"Patience and gentleness holding a relationship steady through a difficult moment.","career":"Quiet persistence and composure under pressure outperform aggression right now.","finance":"Restraint and steady nerve serve better than a forceful, impulsive move.","spiritual":"Symbolically, the taming of instinct through compassion rather than suppression."}'::jsonb, yes_no = 'yes' WHERE id = 9 AND num = 8;
UPDATE tarot_cards SET slug = 'the-hermit', name_en = 'The Hermit', keywords_ru = ARRAY['самоанализ', 'уединение', 'внутренний голос', 'отстранение']::text[], keywords_en = ARRAY['introspection', 'solitude', 'inner guidance', 'withdrawal']::text[], description_ru = 'В одиночестве на горной вершине он держит фонарь, освещающий лишь небольшой круг пути — ровно столько, чтобы сделать следующий шаг.', description_en = 'Alone on a mountain peak, a lantern held aloft, he lights a small circle of the path — enough to take the next step.', meaning_upright = 'Время отступить и заглянуть внутрь; ответ может прийти из уединения, а не из очередного чужого мнения.', meaning_reversed = 'Слишком затянувшаяся изоляция или уход от вопроса, на который одиночество само не ответит.', meaning_upright_en = 'A season for stepping back and looking inward; the answer may come from solitude rather than another opinion.', meaning_reversed_en = 'Isolation that has gone on too long, or avoiding a question that solitude alone won''t answer.', meanings_ru = '{"upright":"Время отступить и заглянуть внутрь; ответ может прийти из уединения, а не из очередного чужого мнения.","reversed":"Слишком затянувшаяся изоляция или уход от вопроса, на который одиночество само не ответит.","love":"Потребность в пространстве, размышлении или времени порознь, пока не прояснится следующий шаг.","career":"Самостоятельная сосредоточенная работа; хороший период для исследований, а не для совместных проектов.","finance":"Время тихо пересмотреть и обдумать, а не действовать.","spiritual":"Символически — фонарь, обращённый внутрь: мудрость, обретаемая через осознанное уединение."}'::jsonb, meanings_en = '{"upright":"A season for stepping back and looking inward; the answer may come from solitude rather than another opinion.","reversed":"Isolation that has gone on too long, or avoiding a question that solitude alone won''t answer.","love":"A need for space, reflection, or time apart before the next step becomes clear.","career":"Independent, focused work; a good period for research over collaboration.","finance":"A time to quietly review and reflect rather than act.","spiritual":"Symbolically, the inward-turned lantern — wisdom found through deliberate withdrawal."}'::jsonb, yes_no = 'maybe' WHERE id = 10 AND num = 9;
UPDATE tarot_cards SET slug = 'wheel-of-fortune', name_en = 'Wheel of Fortune', keywords_ru = ARRAY['циклы', 'судьба', 'поворотные моменты', 'перемены']::text[], keywords_en = ARRAY['cycles', 'fate', 'turning points', 'change']::text[], description_ru = 'Огромное колесо вращается в небе, вознося и опуская символические фигуры — неустанный ритм самих перемен.', description_en = 'A great wheel turns in the sky, carrying symbolic figures up and down — the ceaseless rhythm of change itself.', meaning_upright = 'Поворотный момент, наступающий в своё время, — эта карта может означать перемены, где важнее не контроль, а то, как вы их встречаете.', meaning_reversed = 'Полоса сопротивления или цикл, который кажется застрявшим, — стоит помнить, что колесо продолжает вращаться.', meaning_upright_en = 'A turning point arriving on its own timing — this card can represent change that''s less about control and more about how you meet it.', meaning_reversed_en = 'A run of resistance or a cycle that feels stuck — worth remembering the wheel keeps turning regardless.', meanings_ru = '{"upright":"Поворотный момент, наступающий в своё время, — эта карта может означать перемены, где важнее не контроль, а то, как вы их встречаете.","reversed":"Полоса сопротивления или цикл, который кажется застрявшим, — стоит помнить, что колесо продолжает вращаться.","love":"Отношения вступают в новую фазу, определяемую обстоятельствами не меньше, чем выбором.","career":"Неожиданный сдвиг — шанс, за которым стоит наблюдать, а не форсировать его.","finance":"Время удачи сейчас не полностью в ваших руках — стоит планировать на оба направления.","spiritual":"Символически — цикличность судьбы: ничто не остаётся неизменным навсегда, к лучшему или к худшему."}'::jsonb, meanings_en = '{"upright":"A turning point arriving on its own timing — this card can represent change that''s less about control and more about how you meet it.","reversed":"A run of resistance or a cycle that feels stuck — worth remembering the wheel keeps turning regardless.","love":"A relationship entering a new phase, shaped by circumstance as much as choice.","career":"An unexpected shift — a chance worth watching for rather than forcing.","finance":"Fortune''s timing is not fully within your control right now — plan for both directions.","spiritual":"Symbolically, the cyclical nature of fate — nothing stays fixed forever, for better or worse."}'::jsonb, yes_no = 'maybe' WHERE id = 11 AND num = 10;
UPDATE tarot_cards SET slug = 'justice', name_en = 'Justice', keywords_ru = ARRAY['справедливость', 'истина', 'ответственность', 'причина и следствие']::text[], keywords_en = ARRAY['fairness', 'truth', 'accountability', 'cause and effect']::text[], description_ru = 'Восседая между двумя колоннами, с прямым мечом и уравновешенными весами, она взвешивает ситуацию, не отступая перед правдой.', description_en = 'Seated between two pillars, sword upright and scales balanced, she weighs the situation without flinching from the truth.', meaning_upright = 'Справедливость, истина и последствия, настигающие ситуацию, — это может указывать на момент, когда честность служит вам лучше всего.', meaning_reversed = 'Дисбаланс, несправедливая ситуация или уход от ответственности, который, скорее всего, снова даст о себе знать.', meaning_upright_en = 'Fairness, truth, and consequence catching up with a situation — this can point to a moment where honesty serves you best.', meaning_reversed_en = 'An imbalance, an unfair situation, or avoidance of accountability that''s likely to resurface.', meanings_ru = '{"upright":"Справедливость, истина и последствия, настигающие ситуацию, — это может указывать на момент, когда честность служит вам лучше всего.","reversed":"Дисбаланс, несправедливая ситуация или уход от ответственности, который, скорее всего, снова даст о себе знать.","love":"Отношениям нужна честность или справедливое перераспределение отдачи и получения.","career":"Решение, переговоры или оценка, где прямота окупается.","finance":"Договоры, соглашения или долги, вероятно, требуют трезвого взгляда прямо сейчас.","spiritual":"Символически — причина и следствие, ставшие видимыми: кармический баланс, сводящий счёты."}'::jsonb, meanings_en = '{"upright":"Fairness, truth, and consequence catching up with a situation — this can point to a moment where honesty serves you best.","reversed":"An imbalance, an unfair situation, or avoidance of accountability that''s likely to resurface.","love":"A relationship needing honesty or a fair rebalancing of give-and-take.","career":"A decision, negotiation, or evaluation where being straightforward pays off.","finance":"Contracts, agreements, or debts likely need a clear-eyed look right now.","spiritual":"Symbolically, cause and effect made visible — the karmic ledger balancing itself."}'::jsonb, yes_no = 'yes-if-cautious' WHERE id = 12 AND num = 11;
UPDATE tarot_cards SET slug = 'the-hanged-man', name_en = 'The Hanged Man', keywords_ru = ARRAY['принятие', 'новый взгляд', 'пауза', 'отпускание']::text[], keywords_en = ARRAY['surrender', 'new perspective', 'pause', 'letting go']::text[], description_ru = 'Подвешенный вниз головой на живом дереве, он выглядит скорее спокойным, чем страдающим, — добровольная пауза, а не наказание.', description_en = 'Suspended upside-down from a living tree, his expression is calm rather than pained — a willing pause, not a punishment.', meaning_upright = 'Осознанная пауза, открывающая иной взгляд, — иногда самое полезное действие состоит в том, чтобы перестать давить.', meaning_reversed = 'Ненужная задержка, жертвенность ради жертвенности или сопротивление смене взгляда, которая действительно помогла бы.', meaning_upright_en = 'A deliberate pause that reveals a different point of view — sometimes the most useful move is to stop pushing.', meaning_reversed_en = 'Needless delay, martyrdom, or resisting a perspective shift that would actually help.', meanings_ru = '{"upright":"Осознанная пауза, открывающая иной взгляд, — иногда самое полезное действие состоит в том, чтобы перестать давить.","reversed":"Ненужная задержка, жертвенность ради жертвенности или сопротивление смене взгляда, которая действительно помогла бы.","love":"Отношения на паузе или взгляд на партнёра под совершенно новым углом.","career":"Застопорившемуся проекту может быть нужна смена взгляда, а не больше усилий.","finance":"Не время для крупного шага — лучше подождать и сначала всё ясно увидеть.","spiritual":"Символически — принятие как форма прозрения: отпустить, чтобы увидеть скрытое."}'::jsonb, meanings_en = '{"upright":"A deliberate pause that reveals a different point of view — sometimes the most useful move is to stop pushing.","reversed":"Needless delay, martyrdom, or resisting a perspective shift that would actually help.","love":"A relationship on hold, or seeing a partner from an entirely new angle.","career":"A stalled project may need a change in perspective rather than more effort.","finance":"Not the moment for a big move — better to wait and see clearly first.","spiritual":"Symbolically, surrender as a form of insight — letting go to see what was hidden."}'::jsonb, yes_no = 'no' WHERE id = 13 AND num = 12;
UPDATE tarot_cards SET slug = 'death', name_en = 'Death', keywords_ru = ARRAY['трансформация', 'завершения', 'переход', 'освобождение']::text[], keywords_en = ARRAY['transformation', 'endings', 'transition', 'release']::text[], description_ru = 'Скелет-всадник спокойно движется сквозь меняющийся пейзаж, пока старый мир уступает место тому, что придёт следом, — завершения, освобождающие место для нового.', description_en = 'A skeletal rider moves calmly through a changing landscape as the old world gives way to what comes after — endings that clear space for something new.', meaning_upright = 'Значительное завершение, освобождающее место для трансформации, — редко буквальное, почти всегда о высвобождении и обновлении.', meaning_reversed = 'Сопротивление необходимым переменам или завершение, затянувшееся дольше, чем нужно.', meaning_upright_en = 'A significant ending that makes room for transformation — rarely literal, almost always about release and renewal.', meaning_reversed_en = 'Resistance to a necessary change, or an ending being dragged out longer than it needs to be.', meanings_ru = '{"upright":"Значительное завершение, освобождающее место для трансформации, — редко буквальное, почти всегда о высвобождении и обновлении.","reversed":"Сопротивление необходимым переменам или завершение, затянувшееся дольше, чем нужно.","love":"Отношения или их шаблон подходят к естественному концу, открывая место для следующего.","career":"Конец роли, проекта или подхода — вероятно, необходимый.","finance":"Финансовая глава закрывается; это может быть неудобно, но, скорее всего, расчищает путь вперёд.","spiritual":"Символически — трансформация через освобождение: ничто новое не растёт, пока что-то другое не закончится."}'::jsonb, meanings_en = '{"upright":"A significant ending that makes room for transformation — rarely literal, almost always about release and renewal.","reversed":"Resistance to a necessary change, or an ending being dragged out longer than it needs to be.","love":"A relationship or relationship pattern reaching a natural close, opening space for what''s next.","career":"The end of a role, project, or approach — likely a necessary one.","finance":"A financial chapter closing; may be uncomfortable but is likely clearing the way forward.","spiritual":"Symbolically, transformation through release — nothing new grows without something else ending."}'::jsonb, yes_no = 'no' WHERE id = 14 AND num = 13;
UPDATE tarot_cards SET slug = 'temperance', name_en = 'Temperance', keywords_ru = ARRAY['баланс', 'терпение', 'умеренность', 'интеграция']::text[], keywords_en = ARRAY['balance', 'patience', 'moderation', 'integration']::text[], description_ru = 'Ангел переливает воду из чаши в чашу, стоя одной ногой на земле, а другой в потоке, — смешивая противоположности в единое целое.', description_en = 'An angel pours water between two cups, one foot on land and one in the stream — blending opposites into something whole.', meaning_upright = 'Баланс и терпеливое смешение противоположностей — этот расклад может говорить, что срединный путь служит лучше крайности.', meaning_reversed = 'Дисбаланс, излишество или нетерпение, выводящие всё из пропорции.', meaning_upright_en = 'Balance and patient blending of opposites — this reading may suggest the middle path serves better than an extreme.', meaning_reversed_en = 'Imbalance, excess, or impatience pulling things out of proportion.', meanings_ru = '{"upright":"Баланс и терпеливое смешение противоположностей — этот расклад может говорить, что срединный путь служит лучше крайности.","reversed":"Дисбаланс, излишество или нетерпение, выводящие всё из пропорции.","love":"Отношения находят равновесие через компромисс и терпение.","career":"Ровный, умеренный прогресс; сочетание навыков или подходов работает лучше, чем выбор чего-то одного.","finance":"Умеренность и постепенное, продуманное планирование вместо резких шагов.","spiritual":"Символически — алхимия: терпеливое соединение противоположных начал в гармонию."}'::jsonb, meanings_en = '{"upright":"Balance and patient blending of opposites — this reading may suggest the middle path serves better than an extreme.","reversed":"Imbalance, excess, or impatience pulling things out of proportion.","love":"A relationship finding its equilibrium through compromise and patience.","career":"Steady, moderate progress; combining skills or approaches works better than picking just one.","finance":"Moderation and gradual, well-blended planning over any drastic move.","spiritual":"Symbolically, alchemy — the patient integration of opposing elements into harmony."}'::jsonb, yes_no = 'yes' WHERE id = 15 AND num = 14;
UPDATE tarot_cards SET slug = 'the-devil', name_en = 'The Devil', keywords_ru = ARRAY['привязанность', 'ограничение', 'искушение', 'тень']::text[], keywords_en = ARRAY['attachment', 'restriction', 'temptation', 'shadow']::text[], description_ru = 'Две фигуры стоят на цепи перед рогатым существом, но цепи на их шеях висят достаточно свободно, чтобы их можно было снять.', description_en = 'Two figures stand chained before a horned figure, yet the chains around their necks hang loose enough to remove.', meaning_upright = 'Привычка, шаблон или отношения, которые ощущаются как оковы, — эта карта может означать ограничение, выбранное скорее добровольно, чем кажется сначала.', meaning_reversed = 'Освобождение от ограничивающего шаблона или наконец признание оков, наложенных на себя самим.', meaning_upright_en = 'A pattern, habit, or relationship that feels binding — this card can represent restriction that is more chosen than it first appears.', meaning_reversed_en = 'Breaking free from a limiting pattern, or finally recognizing a form of self-imposed bondage.', meanings_ru = '{"upright":"Привычка, шаблон или отношения, которые ощущаются как оковы, — эта карта может означать ограничение, выбранное скорее добровольно, чем кажется сначала.","reversed":"Освобождение от ограничивающего шаблона или наконец признание оков, наложенных на себя самим.","love":"Сильная, возможно созависимая или нездоровая привязанность, которую стоит честно рассмотреть.","career":"Ощущение ловушки в работе или ситуации, из которой, возможно, больше выходов, чем кажется.","finance":"Следите за перерасходом, долгами или привязанностью к материальному, влияющей на решения.","spiritual":"Символически — теневое «я»: желания и страхи, что связывают, пока их не вынесут на свет."}'::jsonb, meanings_en = '{"upright":"A pattern, habit, or relationship that feels binding — this card can represent restriction that is more chosen than it first appears.","reversed":"Breaking free from a limiting pattern, or finally recognizing a form of self-imposed bondage.","love":"An intense, possibly codependent or unhealthy attachment worth examining honestly.","career":"Feeling trapped by a job or situation that may have more exit options than it seems.","finance":"Watch for overspending, debt, or material attachment driving decisions.","spiritual":"Symbolically, the shadow self — desires and fears that bind until they''re brought into the light."}'::jsonb, yes_no = 'no' WHERE id = 16 AND num = 15;
UPDATE tarot_cards SET slug = 'the-tower', name_en = 'The Tower', keywords_ru = ARRAY['внезапные перемены', 'потрясение', 'прозрение', 'крушение']::text[], keywords_en = ARRAY['sudden change', 'upheaval', 'revelation', 'collapse']::text[], description_ru = 'Молния раскалывает вершину башни, и её обитатели падают вниз — строение на шатком основании стремительно рушится.', description_en = 'Lightning splits a tower''s crown as its occupants fall — a structure built on a shaky foundation coming down fast.', meaning_upright = 'Внезапная, разрушительная перемена, ломающая нечто неустойчивое, — часто шокирующая, но нередко расчищающая то, что всё равно не устояло бы.', meaning_reversed = 'Едва избежанная катастрофа или отсроченный, а не предотвращённый крах.', meaning_upright_en = 'A sudden, disruptive change that breaks down something unstable — often shocking, but frequently clearing away what couldn''t have lasted anyway.', meaning_reversed_en = 'Disaster narrowly avoided, or a collapse delayed rather than prevented.', meanings_ru = '{"upright":"Внезапная, разрушительная перемена, ломающая нечто неустойчивое, — часто шокирующая, но нередко расчищающая то, что всё равно не устояло бы.","reversed":"Едва избежанная катастрофа или отсроченный, а не предотвращённый крах.","love":"Резкое, вскрывающее потрясение — болезненное, но, возможно, обнажающее правду, которой нужно было всплыть.","career":"Неожиданный удар по роли или плану, скорее всего требующий настоящей перестройки, а не заплатки.","finance":"Внезапный откат — важнее всего затем выстроить более устойчивую основу.","spiritual":"Символически — необходимое разрушение: обрушение ложных конструкций, открывающее истину."}'::jsonb, meanings_en = '{"upright":"A sudden, disruptive change that breaks down something unstable — often shocking, but frequently clearing away what couldn''t have lasted anyway.","reversed":"Disaster narrowly avoided, or a collapse delayed rather than prevented.","love":"An abrupt, revealing shake-up — painful, but possibly exposing a truth that needed to surface.","career":"An unexpected disruption to a role or plan, likely demanding a real rebuild rather than a patch.","finance":"A sudden setback — building a more resilient foundation afterward matters most.","spiritual":"Symbolically, necessary destruction — the collapse of false structures to reveal truth."}'::jsonb, yes_no = 'no' WHERE id = 17 AND num = 16;
UPDATE tarot_cards SET slug = 'the-star', name_en = 'The Star', keywords_ru = ARRAY['надежда', 'обновление', 'вдохновение', 'исцеление']::text[], keywords_en = ARRAY['hope', 'renewal', 'inspiration', 'healing']::text[], description_ru = 'Под звёздным небом фигура преклоняет колени у кромки воды, возливая её на землю и в водоём, — тихое обновление после бури.', description_en = 'Beneath a sky full of stars, a figure kneels at the water''s edge, pouring water onto both land and pool — quiet renewal after a storm.', meaning_upright = 'Надежда и исцеление после трудного отрезка — этот расклад может говорить о более спокойной, вдохновляющей почве впереди.', meaning_reversed = 'Упадок духа или потеря веры в лучший исход, скорее всего временная.', meaning_upright_en = 'Hope and healing after a difficult stretch — this reading may suggest calmer, more inspired ground ahead.', meaning_reversed_en = 'Discouragement, or a loss of faith in a better outcome that''s likely temporary.', meanings_ru = '{"upright":"Надежда и исцеление после трудного отрезка — этот расклад может говорить о более спокойной, вдохновляющей почве впереди.","reversed":"Упадок духа или потеря веры в лучший исход, скорее всего временная.","love":"Возрождающаяся надежда, исцеление и более мягкая, оптимистичная фаза.","career":"Вдохновение возвращается после сложного периода; хорошее время снова мечтать чуть смелее.","finance":"Медленное, обнадёживающее улучшение, а не резкое.","spiritual":"Символически — восстановленная вера: путеводный свет после прохождения через тьму."}'::jsonb, meanings_en = '{"upright":"Hope and healing after a difficult stretch — this reading may suggest calmer, more inspired ground ahead.","reversed":"Discouragement, or a loss of faith in a better outcome that''s likely temporary.","love":"Renewed hope, healing, and a gentler, more optimistic phase.","career":"Inspiration returning after a rough patch; a good time to dream a little bigger again.","finance":"A slow, hopeful improvement rather than a dramatic one.","spiritual":"Symbolically, faith restored — a guiding light after passing through darkness."}'::jsonb, yes_no = 'yes' WHERE id = 18 AND num = 17;
UPDATE tarot_cards SET slug = 'the-moon', name_en = 'The Moon', keywords_ru = ARRAY['неопределённость', 'иллюзия', 'интуиция', 'бессознательное']::text[], keywords_en = ARRAY['uncertainty', 'illusion', 'intuition', 'the unconscious']::text[], description_ru = 'Под луной, источающей свет, тропа вьётся между двумя башнями мимо волка, собаки и одинокого ползущего существа — знакомые силуэты, ставшие странными в тусклом свете.', description_en = 'Beneath a moon dripping light, a path winds between two towers, past a wolf, a dog, and a lone crawling creature — familiar shapes made strange in dim light.', meaning_upright = 'Не всё может быть таким, каким кажется, — время двигаться осторожно и доверять интуиции больше, чем поверхностным впечатлениям.', meaning_reversed = 'Рассеивающаяся путаница или скрытая правда, наконец выходящая на более ясный свет.', meaning_upright_en = 'Things may not be entirely as they appear — this can be a time to move carefully and trust intuition over surface impressions.', meaning_reversed_en = 'Confusion lifting, or a hidden truth finally coming into clearer light.', meanings_ru = '{"upright":"Не всё может быть таким, каким кажется, — время двигаться осторожно и доверять интуиции больше, чем поверхностным впечатлениям.","reversed":"Рассеивающаяся путаница или скрытая правда, наконец выходящая на более ясный свет.","love":"Смешанные сигналы или невысказанная тревога, заслуживающие более пристального и спокойного взгляда.","career":"Неясная ситуация на работе — прежде чем что-либо решать, может понадобиться больше информации.","finance":"Неопределённость или неполные данные — возможно, не лучший момент для крупного финансового прыжка.","spiritual":"Символически — бессознательное: сны, страхи и интуиция, всплывающие после наступления темноты."}'::jsonb, meanings_en = '{"upright":"Things may not be entirely as they appear — this can be a time to move carefully and trust intuition over surface impressions.","reversed":"Confusion lifting, or a hidden truth finally coming into clearer light.","love":"Mixed signals or unspoken anxieties that deserve a closer, calmer look.","career":"An unclear situation at work — more information may be needed before deciding anything.","finance":"Uncertainty or incomplete information — this may not be the moment for a big financial leap.","spiritual":"Symbolically, the unconscious mind — dreams, fears, and intuition surfacing after dark."}'::jsonb, yes_no = 'no' WHERE id = 19 AND num = 18;
UPDATE tarot_cards SET slug = 'the-sun', name_en = 'The Sun', keywords_ru = ARRAY['радость', 'жизненная сила', 'ясность', 'успех']::text[], keywords_en = ARRAY['joy', 'vitality', 'clarity', 'success']::text[], description_ru = 'Ребёнок едет верхом с непокрытой головой и радостью под широким сияющим солнцем, а за невысокой садовой оградой поднимаются подсолнухи.', description_en = 'A child rides bareheaded and joyful beneath a wide, radiant sun, sunflowers rising behind a low garden wall.', meaning_upright = 'Ясность, радость и в целом хорошо идущие дела — эта карта может означать по-настоящему светлый, энергичный период.', meaning_reversed = 'Омрачённая радость, временные неудачи или успех, который ещё не совсем наступил.', meaning_upright_en = 'Clarity, joy, and things generally going well — this card can represent a genuinely bright, energized period.', meaning_reversed_en = 'Clouded joy, temporary setbacks, or success that hasn''t quite arrived yet.', meanings_ru = '{"upright":"Ясность, радость и в целом хорошо идущие дела — эта карта может означать по-настоящему светлый, энергичный период.","reversed":"Омрачённая радость, временные неудачи или успех, который ещё не совсем наступил.","love":"Тепло, открытость и настоящее счастье в отношениях.","career":"Признание, успех или просто снова радость от работы.","finance":"Позитивный, трезвый период для роста.","spiritual":"Символически — просветление и жизненная сила: «я» в самом открытом и живом состоянии."}'::jsonb, meanings_en = '{"upright":"Clarity, joy, and things generally going well — this card can represent a genuinely bright, energized period.","reversed":"Clouded joy, temporary setbacks, or success that hasn''t quite arrived yet.","love":"Warmth, openness, and genuine happiness in a connection.","career":"Recognition, success, or simply enjoying the work again.","finance":"A positive, clear-headed period for growth.","spiritual":"Symbolically, enlightenment and vitality — the self at its most unguarded and alive."}'::jsonb, yes_no = 'yes' WHERE id = 20 AND num = 19;
UPDATE tarot_cards SET slug = 'judgement', name_en = 'Judgement', keywords_ru = ARRAY['итог', 'обновление', 'самооценка', 'пробуждение']::text[], keywords_en = ARRAY['reckoning', 'renewal', 'self-evaluation', 'awakening']::text[], description_ru = 'Фигуры восстают из разверзшихся могил, пока ангел трубит в трубу над ними, — призыв честно подвести итог и восстать обновлённым.', description_en = 'Figures rise from open graves as an angel sounds a trumpet overhead — a call to reckon honestly and rise renewed.', meaning_upright = 'Момент честной самооценки и пробуждения — этот расклад может указывать на решение, которое давно ждёт своего часа.', meaning_reversed = 'Слишком суровый самосуд или уход от давно назревшего подведения итогов.', meaning_upright_en = 'A moment of honest self-evaluation and awakening — this reading may point toward a decision that''s been waiting to be made.', meaning_reversed_en = 'Self-judgment that''s too harsh, or avoiding a reckoning that''s overdue.', meanings_ru = '{"upright":"Момент честной самооценки и пробуждения — этот расклад может указывать на решение, которое давно ждёт своего часа.","reversed":"Слишком суровый самосуд или уход от давно назревшего подведения итогов.","love":"Отношения честно оцениваются, что может привести к возобновлённой преданности или ясному завершению.","career":"Профессиональный итог — оценка того, подходит ли нынешний путь тому, кем вы стали.","finance":"Честный пересмотр прошлых решений перед тем, как двигаться дальше.","spiritual":"Символически — возрождение через честный итог: пробуждение, следующее за самоанализом."}'::jsonb, meanings_en = '{"upright":"A moment of honest self-evaluation and awakening — this reading may point toward a decision that''s been waiting to be made.","reversed":"Self-judgment that''s too harsh, or avoiding a reckoning that''s overdue.","love":"A relationship being evaluated honestly, possibly leading to renewed commitment or a clear ending.","career":"A career reckoning — evaluating whether the current path still fits who you''ve become.","finance":"Reviewing past decisions honestly before moving forward.","spiritual":"Symbolically, rebirth through honest reckoning — an awakening that follows self-examination."}'::jsonb, yes_no = 'yes' WHERE id = 21 AND num = 20;
UPDATE tarot_cards SET slug = 'the-world', name_en = 'The World', keywords_ru = ARRAY['завершение', 'целостность', 'исполнение', 'интеграция']::text[], keywords_en = ARRAY['completion', 'wholeness', 'fulfillment', 'integration']::text[], description_ru = 'Фигура танцует в лавровом венке, а из каждого угла за ней наблюдают четыре символических существа — завершённый цикл, целостный и объединённый.', description_en = 'A figure dances within a laurel wreath, four symbolic creatures watching from each corner — a cycle completed, whole and integrated.', meaning_upright = 'Завершение и интеграция — это может быть карта закрытия значимой главы и подлинного ощущения целостности.', meaning_reversed = 'Нечто оставшееся незавершённым или ощущение близости к финалу, но не полное.', meaning_upright_en = 'Completion and integration — this can be a card of finishing a meaningful chapter and feeling genuinely whole.', meaning_reversed_en = 'Something left unfinished, or a sense of being close to completion but not quite there.', meanings_ru = '{"upright":"Завершение и интеграция — это может быть карта закрытия значимой главы и подлинного ощущения целостности.","reversed":"Нечто оставшееся незавершённым или ощущение близости к финалу, но не полное.","love":"Отношения достигают исполненной вехи или удовлетворяющего чувства целостности.","career":"Проект или цель по-настоящему завершаются — естественный момент отметить это перед следующим.","finance":"Достигнутая цель или финансовый цикл, завершённый удовлетворительно.","spiritual":"Символически — целостность: конец одного цикла, который одновременно дверь в следующий."}'::jsonb, meanings_en = '{"upright":"Completion and integration — this can be a card of finishing a meaningful chapter and feeling genuinely whole.","reversed":"Something left unfinished, or a sense of being close to completion but not quite there.","love":"A relationship reaching a fulfilling milestone or a satisfying sense of wholeness.","career":"A project or goal reaching real completion — a natural point to acknowledge before starting the next one.","finance":"A goal achieved or a financial cycle brought to a satisfying close.","spiritual":"Symbolically, wholeness — the end of one cycle that is, at the same time, the doorway to the next."}'::jsonb, yes_no = 'yes' WHERE id = 22 AND num = 21;
UPDATE tarot_cards SET slug = 'ace-of-wands', name_en = 'Ace of Wands', keywords_ru = ARRAY['новое начало', 'огонь', 'жезлы']::text[], keywords_en = ARRAY['new beginning', 'fire', 'wands']::text[], description_ru = 'Карта «Туз Жезлов» отражает страсти, амбиций и творческого порыва через призму темы «новое начало».', description_en = 'The ace of the wands suit, carrying passion, ambition, and creative drive through the lens of new beginning.', meaning_upright = 'Чистая, ничем не разбавленная искра страсти, амбиций и творческого порыва — возможность или предложение, приходящие в самой простой и мощной форме.', meaning_reversed = 'Ложный старт, упущенная возможность или порыв в сфере страсти, амбиций и творческого порыва, заблокированный до того, как успел пустить корни.', meaning_upright_en = 'A pure, undiluted spark of passion, ambition, and creative drive — an opening or offer arriving in its simplest, most potent form.', meaning_reversed_en = 'A false start, a missed opening, or passion, ambition, and creative drive blocked before it can take root.', meanings_ru = '{"upright":"Чистая, ничем не разбавленная искра страсти, амбиций и творческого порыва — возможность или предложение, приходящие в самой простой и мощной форме.","reversed":"Ложный старт, упущенная возможность или порыв в сфере страсти, амбиций и творческого порыва, заблокированный до того, как успел пустить корни.","love":"В делах сердца эта карта опирается на страсть, азарт и химию — символически, сфера страсти, амбиций и творческого порыва разворачивается между двумя людьми.","career":"На работе это указывает на инициативу, амбиции и творческий импульс.","finance":"В финансах это говорит о смелых, энергичных шагах — их стоит сочетать с планом.","spiritual":"В духовном плане одна из возможных трактовок связана с творческой волей и искрой, с которой всё начинается."}'::jsonb, meanings_en = '{"upright":"A pure, undiluted spark of passion, ambition, and creative drive — an opening or offer arriving in its simplest, most potent form.","reversed":"A false start, a missed opening, or passion, ambition, and creative drive blocked before it can take root.","love":"In matters of the heart, this card leans on passion, excitement, and chemistry — symbolically, passion, ambition, and creative drive playing out between two people.","career":"At work, this points to initiative, ambition, and creative momentum.","finance":"Financially, this suggests bold, energetic moves — worth pairing with a plan.","spiritual":"Spiritually, one possible interpretation centers on the creative will and the spark that starts things."}'::jsonb, yes_no = 'yes' WHERE id = 23 AND num = 1;
UPDATE tarot_cards SET slug = 'two-of-wands', name_en = 'Two of Wands', keywords_ru = ARRAY['выбор', 'огонь', 'жезлы']::text[], keywords_en = ARRAY['choice', 'fire', 'wands']::text[], description_ru = 'Карта «Двойка Жезлов» отражает страсти, амбиций и творческого порыва через призму темы «выбор».', description_en = 'The two of the wands suit, carrying passion, ambition, and creative drive through the lens of choice.', meaning_upright = 'Выбор или партнёрство, складывающиеся в сфере страсти, амбиций и творческого порыва: два пути или два человека вместе взвешивают варианты.', meaning_reversed = 'Нерешительность, дисбаланс или партнёрство в сфере страсти, амбиций и творческого порыва, где вклад распределён неравномерно.', meaning_upright_en = 'A choice or partnership taking shape within passion, ambition, and creative drive — two paths, or two people, weighing options together.', meaning_reversed_en = 'Indecision, imbalance, or a partnership within passion, ambition, and creative drive that isn''t pulling its weight evenly.', meanings_ru = '{"upright":"Выбор или партнёрство, складывающиеся в сфере страсти, амбиций и творческого порыва: два пути или два человека вместе взвешивают варианты.","reversed":"Нерешительность, дисбаланс или партнёрство в сфере страсти, амбиций и творческого порыва, где вклад распределён неравномерно.","love":"В делах сердца эта карта опирается на страсть, азарт и химию — символически, сфера страсти, амбиций и творческого порыва разворачивается между двумя людьми.","career":"На работе это указывает на инициативу, амбиции и творческий импульс.","finance":"В финансах это говорит о смелых, энергичных шагах — их стоит сочетать с планом.","spiritual":"В духовном плане одна из возможных трактовок связана с творческой волей и искрой, с которой всё начинается."}'::jsonb, meanings_en = '{"upright":"A choice or partnership taking shape within passion, ambition, and creative drive — two paths, or two people, weighing options together.","reversed":"Indecision, imbalance, or a partnership within passion, ambition, and creative drive that isn''t pulling its weight evenly.","love":"In matters of the heart, this card leans on passion, excitement, and chemistry — symbolically, passion, ambition, and creative drive playing out between two people.","career":"At work, this points to initiative, ambition, and creative momentum.","finance":"Financially, this suggests bold, energetic moves — worth pairing with a plan.","spiritual":"Spiritually, one possible interpretation centers on the creative will and the spark that starts things."}'::jsonb, yes_no = 'maybe' WHERE id = 24 AND num = 2;
UPDATE tarot_cards SET slug = 'three-of-wands', name_en = 'Three of Wands', keywords_ru = ARRAY['рост', 'огонь', 'жезлы']::text[], keywords_en = ARRAY['growth', 'fire', 'wands']::text[], description_ru = 'Карта «Тройка Жезлов» отражает страсти, амбиций и творческого порыва через призму темы «рост».', description_en = 'The three of the wands suit, carrying passion, ambition, and creative drive through the lens of growth.', meaning_upright = 'Первые результаты и движение вперёд в сфере страсти, амбиций и творческого порыва — первая видимая отдача от уже приложенных усилий.', meaning_reversed = 'Задержки, разочарование или рост в сфере страсти, амбиций и творческого порыва, остановившийся в шаге от результата.', meaning_upright_en = 'Early results and forward motion in passion, ambition, and creative drive — the first visible payoff of effort already made.', meaning_reversed_en = 'Delays, disappointment, or growth in passion, ambition, and creative drive that has stalled just short of paying off.', meanings_ru = '{"upright":"Первые результаты и движение вперёд в сфере страсти, амбиций и творческого порыва — первая видимая отдача от уже приложенных усилий.","reversed":"Задержки, разочарование или рост в сфере страсти, амбиций и творческого порыва, остановившийся в шаге от результата.","love":"В делах сердца эта карта опирается на страсть, азарт и химию — символически, сфера страсти, амбиций и творческого порыва разворачивается между двумя людьми.","career":"На работе это указывает на инициативу, амбиции и творческий импульс.","finance":"В финансах это говорит о смелых, энергичных шагах — их стоит сочетать с планом.","spiritual":"В духовном плане одна из возможных трактовок связана с творческой волей и искрой, с которой всё начинается."}'::jsonb, meanings_en = '{"upright":"Early results and forward motion in passion, ambition, and creative drive — the first visible payoff of effort already made.","reversed":"Delays, disappointment, or growth in passion, ambition, and creative drive that has stalled just short of paying off.","love":"In matters of the heart, this card leans on passion, excitement, and chemistry — symbolically, passion, ambition, and creative drive playing out between two people.","career":"At work, this points to initiative, ambition, and creative momentum.","finance":"Financially, this suggests bold, energetic moves — worth pairing with a plan.","spiritual":"Spiritually, one possible interpretation centers on the creative will and the spark that starts things."}'::jsonb, yes_no = 'yes' WHERE id = 25 AND num = 3;
UPDATE tarot_cards SET slug = 'four-of-wands', name_en = 'Four of Wands', keywords_ru = ARRAY['стабильность', 'огонь', 'жезлы']::text[], keywords_en = ARRAY['stability', 'fire', 'wands']::text[], description_ru = 'Карта «Четвёрка Жезлов» отражает страсти, амбиций и творческого порыва через призму темы «стабильность».', description_en = 'The four of the wands suit, carrying passion, ambition, and creative drive through the lens of stability.', meaning_upright = 'Пауза, чтобы закрепить построенное в сфере страсти, амбиций и творческого порыва, — стабильность, которую стоит оценить, прежде чем двигаться дальше.', meaning_reversed = 'Застой или стабильность в сфере страсти, амбиций и творческого порыва, тихо превратившаяся в колею.', meaning_upright_en = 'A pause to consolidate what''s been built in passion, ambition, and creative drive — stability worth appreciating before pushing further.', meaning_reversed_en = 'Stagnation, or a stability in passion, ambition, and creative drive that has quietly turned into a rut.', meanings_ru = '{"upright":"Пауза, чтобы закрепить построенное в сфере страсти, амбиций и творческого порыва, — стабильность, которую стоит оценить, прежде чем двигаться дальше.","reversed":"Застой или стабильность в сфере страсти, амбиций и творческого порыва, тихо превратившаяся в колею.","love":"В делах сердца эта карта опирается на страсть, азарт и химию — символически, сфера страсти, амбиций и творческого порыва разворачивается между двумя людьми.","career":"На работе это указывает на инициативу, амбиции и творческий импульс.","finance":"В финансах это говорит о смелых, энергичных шагах — их стоит сочетать с планом.","spiritual":"В духовном плане одна из возможных трактовок связана с творческой волей и искрой, с которой всё начинается."}'::jsonb, meanings_en = '{"upright":"A pause to consolidate what''s been built in passion, ambition, and creative drive — stability worth appreciating before pushing further.","reversed":"Stagnation, or a stability in passion, ambition, and creative drive that has quietly turned into a rut.","love":"In matters of the heart, this card leans on passion, excitement, and chemistry — symbolically, passion, ambition, and creative drive playing out between two people.","career":"At work, this points to initiative, ambition, and creative momentum.","finance":"Financially, this suggests bold, energetic moves — worth pairing with a plan.","spiritual":"Spiritually, one possible interpretation centers on the creative will and the spark that starts things."}'::jsonb, yes_no = 'maybe' WHERE id = 26 AND num = 4;
UPDATE tarot_cards SET slug = 'five-of-wands', name_en = 'Five of Wands', keywords_ru = ARRAY['конфликт', 'огонь', 'жезлы']::text[], keywords_en = ARRAY['conflict', 'fire', 'wands']::text[], description_ru = 'Карта «Пятёрка Жезлов» отражает страсти, амбиций и творческого порыва через призму темы «конфликт».', description_en = 'The five of the wands suit, carrying passion, ambition, and creative drive through the lens of conflict.', meaning_upright = 'Трения, соперничество или сбой, проверяющие на прочность сферу страсти, амбиций и творческого порыва, — неприятно, но редко навсегда.', meaning_reversed = 'Конфликт в сфере страсти, амбиций и творческого порыва начинает стихать, или урок из него наконец усваивается.', meaning_upright_en = 'Friction, competition, or disruption testing passion, ambition, and creative drive — uncomfortable, but rarely permanent.', meaning_reversed_en = 'Conflict in passion, ambition, and creative drive beginning to ease, or a lesson from it finally sinking in.', meanings_ru = '{"upright":"Трения, соперничество или сбой, проверяющие на прочность сферу страсти, амбиций и творческого порыва, — неприятно, но редко навсегда.","reversed":"Конфликт в сфере страсти, амбиций и творческого порыва начинает стихать, или урок из него наконец усваивается.","love":"В делах сердца эта карта опирается на страсть, азарт и химию — символически, сфера страсти, амбиций и творческого порыва разворачивается между двумя людьми.","career":"На работе это указывает на инициативу, амбиции и творческий импульс.","finance":"В финансах это говорит о смелых, энергичных шагах — их стоит сочетать с планом.","spiritual":"В духовном плане одна из возможных трактовок связана с творческой волей и искрой, с которой всё начинается."}'::jsonb, meanings_en = '{"upright":"Friction, competition, or disruption testing passion, ambition, and creative drive — uncomfortable, but rarely permanent.","reversed":"Conflict in passion, ambition, and creative drive beginning to ease, or a lesson from it finally sinking in.","love":"In matters of the heart, this card leans on passion, excitement, and chemistry — symbolically, passion, ambition, and creative drive playing out between two people.","career":"At work, this points to initiative, ambition, and creative momentum.","finance":"Financially, this suggests bold, energetic moves — worth pairing with a plan.","spiritual":"Spiritually, one possible interpretation centers on the creative will and the spark that starts things."}'::jsonb, yes_no = 'no' WHERE id = 27 AND num = 5;
UPDATE tarot_cards SET slug = 'six-of-wands', name_en = 'Six of Wands', keywords_ru = ARRAY['гармония', 'огонь', 'жезлы']::text[], keywords_en = ARRAY['harmony', 'fire', 'wands']::text[], description_ru = 'Карта «Шестёрка Жезлов» отражает страсти, амбиций и творческого порыва через призму темы «гармония».', description_en = 'The six of the wands suit, carrying passion, ambition, and creative drive through the lens of harmony.', meaning_upright = 'Возвращение к равновесию и щедрости в сфере страсти, амбиций и творческого порыва — сотрудничество работает в вашу пользу.', meaning_reversed = 'Старый дисбаланс в сфере страсти, амбиций и творческого порыва снова всплывает, или щедрость остаётся без отклика.', meaning_upright_en = 'A return to balance and generosity within passion, ambition, and creative drive — cooperation working in your favor.', meaning_reversed_en = 'An old imbalance in passion, ambition, and creative drive resurfacing, or generosity that isn''t being returned.', meanings_ru = '{"upright":"Возвращение к равновесию и щедрости в сфере страсти, амбиций и творческого порыва — сотрудничество работает в вашу пользу.","reversed":"Старый дисбаланс в сфере страсти, амбиций и творческого порыва снова всплывает, или щедрость остаётся без отклика.","love":"В делах сердца эта карта опирается на страсть, азарт и химию — символически, сфера страсти, амбиций и творческого порыва разворачивается между двумя людьми.","career":"На работе это указывает на инициативу, амбиции и творческий импульс.","finance":"В финансах это говорит о смелых, энергичных шагах — их стоит сочетать с планом.","spiritual":"В духовном плане одна из возможных трактовок связана с творческой волей и искрой, с которой всё начинается."}'::jsonb, meanings_en = '{"upright":"A return to balance and generosity within passion, ambition, and creative drive — cooperation working in your favor.","reversed":"An old imbalance in passion, ambition, and creative drive resurfacing, or generosity that isn''t being returned.","love":"In matters of the heart, this card leans on passion, excitement, and chemistry — symbolically, passion, ambition, and creative drive playing out between two people.","career":"At work, this points to initiative, ambition, and creative momentum.","finance":"Financially, this suggests bold, energetic moves — worth pairing with a plan.","spiritual":"Spiritually, one possible interpretation centers on the creative will and the spark that starts things."}'::jsonb, yes_no = 'yes' WHERE id = 28 AND num = 6;
UPDATE tarot_cards SET slug = 'seven-of-wands', name_en = 'Seven of Wands', keywords_ru = ARRAY['размышление', 'огонь', 'жезлы']::text[], keywords_en = ARRAY['reflection', 'fire', 'wands']::text[], description_ru = 'Карта «Семёрка Жезлов» отражает страсти, амбиций и творческого порыва через призму темы «размышление».', description_en = 'The seven of the wands suit, carrying passion, ambition, and creative drive through the lens of reflection.', meaning_upright = 'Момент оценить стратегию в сфере страсти, амбиций и творческого порыва — настойчивость и честное размышление вместо быстрых действий.', meaning_reversed = 'Сомнения в себе или обходной путь в сфере страсти, амбиций и творческого порыва, который, скорее всего, ещё напомнит о себе.', meaning_upright_en = 'A moment to assess strategy within passion, ambition, and creative drive — perseverance and honest reflection over quick action.', meaning_reversed_en = 'Second-guessing, or a shortcut within passion, ambition, and creative drive that''s likely to catch up with you.', meanings_ru = '{"upright":"Момент оценить стратегию в сфере страсти, амбиций и творческого порыва — настойчивость и честное размышление вместо быстрых действий.","reversed":"Сомнения в себе или обходной путь в сфере страсти, амбиций и творческого порыва, который, скорее всего, ещё напомнит о себе.","love":"В делах сердца эта карта опирается на страсть, азарт и химию — символически, сфера страсти, амбиций и творческого порыва разворачивается между двумя людьми.","career":"На работе это указывает на инициативу, амбиции и творческий импульс.","finance":"В финансах это говорит о смелых, энергичных шагах — их стоит сочетать с планом.","spiritual":"В духовном плане одна из возможных трактовок связана с творческой волей и искрой, с которой всё начинается."}'::jsonb, meanings_en = '{"upright":"A moment to assess strategy within passion, ambition, and creative drive — perseverance and honest reflection over quick action.","reversed":"Second-guessing, or