UPDATE tarot_cards SET slug = 'knight-of-swords', name_en = 'Knight of Swords', keywords_ru = ARRAY['стремление', 'воздух', 'мечи']::text[], keywords_en = ARRAY['pursuit', 'air', 'swords']::text[], description_ru = 'Карта «Рыцарь Мечей» воплощает архетип энергичного искателя в стихии мысли, конфликта и истины.', description_en = 'An energetic pursuer within the swords suit, embodying thought, conflict, and truth.', meaning_upright = 'Энергичное, целеустремлённое движение в сфере мысли, конфликта и истины — действие и напор, к добру или к худу.', meaning_reversed = 'Безрассудство или погоня в сфере мысли, конфликта и истины, ставшая импульсивной или хаотичной.', meaning_upright_en = 'Energetic, single-minded pursuit of thought, conflict, and truth — movement and action, for better or worse.', meaning_reversed_en = 'Recklessness, or pursuit of thought, conflict, and truth that has become impulsive or scattered.', meanings_ru = '{"upright":"Энергичное, целеустремлённое движение в сфере мысли, конфликта и истины — действие и напор, к добру или к худу.","reversed":"Безрассудство или погоня в сфере мысли, конфликта и истины, ставшая импульсивной или хаотичной.","love":"В делах сердца эта карта опирается на общение, честность и то, где слова помогают или ранят — символически, сфера мысли, конфликта и истины разворачивается между двумя людьми.","career":"На работе это указывает на стратегию, решения и ясность ума под давлением.","finance":"В финансах это говорит о договорах, соглашениях и трезвых (не эмоциональных) решениях.","spiritual":"В духовном плане одна из возможных трактовок связана с ясностью, которая рассекает иллюзии, порой болезненно."}'::jsonb, meanings_en = '{"upright":"Energetic, single-minded pursuit of thought, conflict, and truth — movement and action, for better or worse.","reversed":"Recklessness, or pursuit of thought, conflict, and truth that has become impulsive or scattered.","love":"In matters of the heart, this card leans on communication, honesty, and where words help or hurt — symbolically, thought, conflict, and truth playing out between two people.","career":"At work, this points to strategy, decisions, and mental clarity under pressure.","finance":"Financially, this suggests contracts, agreements, and clear-headed (not emotional) choices.","spiritual":"Spiritually, one possible interpretation centers on clarity that cuts through illusion, sometimes painfully."}'::jsonb, yes_no = 'yes-if-cautious' WHERE id = 62 AND num = 12;
UPDATE tarot_cards SET slug = 'queen-of-swords', name_en = 'Queen of Swords', keywords_ru = ARRAY['интуитивное мастерство', 'воздух', 'мечи']::text[], keywords_en = ARRAY['intuitive mastery', 'air', 'swords']::text[], description_ru = 'Карта «Королева Мечей» воплощает архетип интуитивного мастера в стихии мысли, конфликта и истины.', description_en = 'An intuitive master within the swords suit, embodying thought, conflict, and truth.', meaning_upright = 'Интуитивное, глубоко усвоенное мастерство в сфере мысли, конфликта и истины — забота об этой области из прожитого понимания, а не из теории.', meaning_reversed = 'Неуверенность или мастерство в сфере мысли, конфликта и истины, обращённое внутрь и самокритичное вместо щедрого.', meaning_upright_en = 'Intuitive, internalized mastery of thought, conflict, and truth — nurturing this domain from lived understanding rather than theory.', meaning_reversed_en = 'Insecurity, or mastery of thought, conflict, and truth turned inward and self-critical instead of generous.', meanings_ru = '{"upright":"Интуитивное, глубоко усвоенное мастерство в сфере мысли, конфликта и истины — забота об этой области из прожитого понимания, а не из теории.","reversed":"Неуверенность или мастерство в сфере мысли, конфликта и истины, обращённое внутрь и самокритичное вместо щедрого.","love":"В делах сердца эта карта опирается на общение, честность и то, где слова помогают или ранят — символически, сфера мысли, конфликта и истины разворачивается между двумя людьми.","career":"На работе это указывает на стратегию, решения и ясность ума под давлением.","finance":"В финансах это говорит о договорах, соглашениях и трезвых (не эмоциональных) решениях.","spiritual":"В духовном плане одна из возможных трактовок связана с ясностью, которая рассекает иллюзии, порой болезненно."}'::jsonb, meanings_en = '{"upright":"Intuitive, internalized mastery of thought, conflict, and truth — nurturing this domain from lived understanding rather than theory.","reversed":"Insecurity, or mastery of thought, conflict, and truth turned inward and self-critical instead of generous.","love":"In matters of the heart, this card leans on communication, honesty, and where words help or hurt — symbolically, thought, conflict, and truth playing out between two people.","career":"At work, this points to strategy, decisions, and mental clarity under pressure.","finance":"Financially, this suggests contracts, agreements, and clear-headed (not emotional) choices.","spiritual":"Spiritually, one possible interpretation centers on clarity that cuts through illusion, sometimes painfully."}'::jsonb, yes_no = 'yes' WHERE id = 63 AND num = 13;
UPDATE tarot_cards SET slug = 'king-of-swords', name_en = 'King of Swords', keywords_ru = ARRAY['власть', 'воздух', 'мечи']::text[], keywords_en = ARRAY['command', 'air', 'swords']::text[], description_ru = 'Карта «Король Мечей» воплощает архетип властного правителя в стихии мысли, конфликта и истины.', description_en = 'A commanding authority within the swords suit, embodying thought, conflict, and truth.', meaning_upright = 'Уверенное, внешне выраженное владение сферой мысли, конфликта и истины — лидерство на основе опыта и заслуженного авторитета.', meaning_reversed = 'Проблемы с контролем или власть в сфере мысли, конфликта и истины, применяемая жёстко, а не мудро.', meaning_upright_en = 'Confident, externalized command of thought, conflict, and truth — leading from experience and earned authority.', meaning_reversed_en = 'Control issues, or authority over thought, conflict, and truth used rigidly rather than wisely.', meanings_ru = '{"upright":"Уверенное, внешне выраженное владение сферой мысли, конфликта и истины — лидерство на основе опыта и заслуженного авторитета.","reversed":"Проблемы с контролем или власть в сфере мысли, конфликта и истины, применяемая жёстко, а не мудро.","love":"В делах сердца эта карта опирается на общение, честность и то, где слова помогают или ранят — символически, сфера мысли, конфликта и истины разворачивается между двумя людьми.","career":"На работе это указывает на стратегию, решения и ясность ума под давлением.","finance":"В финансах это говорит о договорах, соглашениях и трезвых (не эмоциональных) решениях.","spiritual":"В духовном плане одна из возможных трактовок связана с ясностью, которая рассекает иллюзии, порой болезненно."}'::jsonb, meanings_en = '{"upright":"Confident, externalized command of thought, conflict, and truth — leading from experience and earned authority.","reversed":"Control issues, or authority over thought, conflict, and truth used rigidly rather than wisely.","love":"In matters of the heart, this card leans on communication, honesty, and where words help or hurt — symbolically, thought, conflict, and truth playing out between two people.","career":"At work, this points to strategy, decisions, and mental clarity under pressure.","finance":"Financially, this suggests contracts, agreements, and clear-headed (not emotional) choices.","spiritual":"Spiritually, one possible interpretation centers on clarity that cuts through illusion, sometimes painfully."}'::jsonb, yes_no = 'yes' WHERE id = 64 AND num = 14;
UPDATE tarot_cards SET slug = 'ace-of-pentacles', name_en = 'Ace of Pentacles', keywords_ru = ARRAY['новое начало', 'земля', 'пентакли']::text[], keywords_en = ARRAY['new beginning', 'earth', 'pentacles']::text[], description_ru = 'Карта «Туз Пентаклей» отражает труда, денег и материального мира через призму темы «новое начало».', description_en = 'The ace of the pentacles suit, carrying work, money, and the material world through the lens of new beginning.', meaning_upright = 'Чистая, ничем не разбавленная искра труда, денег и материального мира — возможность или предложение, приходящие в самой простой и мощной форме.', meaning_reversed = 'Ложный старт, упущенная возможность или порыв в сфере труда, денег и материального мира, заблокированный до того, как успел пустить корни.', meaning_upright_en = 'A pure, undiluted spark of work, money, and the material world — an opening or offer arriving in its simplest, most potent form.', meaning_reversed_en = 'A false start, a missed opening, or work, money, and the material world blocked before it can take root.', meanings_ru = '{"upright":"Чистая, ничем не разбавленная искра труда, денег и материального мира — возможность или предложение, приходящие в самой простой и мощной форме.","reversed":"Ложный старт, упущенная возможность или порыв в сфере труда, денег и материального мира, заблокированный до того, как успел пустить корни.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"A pure, undiluted spark of work, money, and the material world — an opening or offer arriving in its simplest, most potent form.","reversed":"A false start, a missed opening, or work, money, and the material world blocked before it can take root.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'yes' WHERE id = 65 AND num = 1;
UPDATE tarot_cards SET slug = 'two-of-pentacles', name_en = 'Two of Pentacles', keywords_ru = ARRAY['выбор', 'земля', 'пентакли']::text[], keywords_en = ARRAY['choice', 'earth', 'pentacles']::text[], description_ru = 'Карта «Двойка Пентаклей» отражает труда, денег и материального мира через призму темы «выбор».', description_en = 'The two of the pentacles suit, carrying work, money, and the material world through the lens of choice.', meaning_upright = 'Выбор или партнёрство, складывающиеся в сфере труда, денег и материального мира: два пути или два человека вместе взвешивают варианты.', meaning_reversed = 'Нерешительность, дисбаланс или партнёрство в сфере труда, денег и материального мира, где вклад распределён неравномерно.', meaning_upright_en = 'A choice or partnership taking shape within work, money, and the material world — two paths, or two people, weighing options together.', meaning_reversed_en = 'Indecision, imbalance, or a partnership within work, money, and the material world that isn''t pulling its weight evenly.', meanings_ru = '{"upright":"Выбор или партнёрство, складывающиеся в сфере труда, денег и материального мира: два пути или два человека вместе взвешивают варианты.","reversed":"Нерешительность, дисбаланс или партнёрство в сфере труда, денег и материального мира, где вклад распределён неравномерно.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"A choice or partnership taking shape within work, money, and the material world — two paths, or two people, weighing options together.","reversed":"Indecision, imbalance, or a partnership within work, money, and the material world that isn''t pulling its weight evenly.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'maybe' WHERE id = 66 AND num = 2;
UPDATE tarot_cards SET slug = 'three-of-pentacles', name_en = 'Three of Pentacles', keywords_ru = ARRAY['рост', 'земля', 'пентакли']::text[], keywords_en = ARRAY['growth', 'earth', 'pentacles']::text[], description_ru = 'Карта «Тройка Пентаклей» отражает труда, денег и материального мира через призму темы «рост».', description_en = 'The three of the pentacles suit, carrying work, money, and the material world through the lens of growth.', meaning_upright = 'Первые результаты и движение вперёд в сфере труда, денег и материального мира — первая видимая отдача от уже приложенных усилий.', meaning_reversed = 'Задержки, разочарование или рост в сфере труда, денег и материального мира, остановившийся в шаге от результата.', meaning_upright_en = 'Early results and forward motion in work, money, and the material world — the first visible payoff of effort already made.', meaning_reversed_en = 'Delays, disappointment, or growth in work, money, and the material world that has stalled just short of paying off.', meanings_ru = '{"upright":"Первые результаты и движение вперёд в сфере труда, денег и материального мира — первая видимая отдача от уже приложенных усилий.","reversed":"Задержки, разочарование или рост в сфере труда, денег и материального мира, остановившийся в шаге от результата.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"Early results and forward motion in work, money, and the material world — the first visible payoff of effort already made.","reversed":"Delays, disappointment, or growth in work, money, and the material world that has stalled just short of paying off.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'yes' WHERE id = 67 AND num = 3;
UPDATE tarot_cards SET slug = 'four-of-pentacles', name_en = 'Four of Pentacles', keywords_ru = ARRAY['стабильность', 'земля', 'пентакли']::text[], keywords_en = ARRAY['stability', 'earth', 'pentacles']::text[], description_ru = 'Карта «Четвёрка Пентаклей» отражает труда, денег и материального мира через призму темы «стабильность».', description_en = 'The four of the pentacles suit, carrying work, money, and the material world through the lens of stability.', meaning_upright = 'Пауза, чтобы закрепить построенное в сфере труда, денег и материального мира, — стабильность, которую стоит оценить, прежде чем двигаться дальше.', meaning_reversed = 'Застой или стабильность в сфере труда, денег и материального мира, тихо превратившаяся в колею.', meaning_upright_en = 'A pause to consolidate what''s been built in work, money, and the material world — stability worth appreciating before pushing further.', meaning_reversed_en = 'Stagnation, or a stability in work, money, and the material world that has quietly turned into a rut.', meanings_ru = '{"upright":"Пауза, чтобы закрепить построенное в сфере труда, денег и материального мира, — стабильность, которую стоит оценить, прежде чем двигаться дальше.","reversed":"Застой или стабильность в сфере труда, денег и материального мира, тихо превратившаяся в колею.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"A pause to consolidate what''s been built in work, money, and the material world — stability worth appreciating before pushing further.","reversed":"Stagnation, or a stability in work, money, and the material world that has quietly turned into a rut.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'maybe' WHERE id = 68 AND num = 4;
UPDATE tarot_cards SET slug = 'five-of-pentacles', name_en = 'Five of Pentacles', keywords_ru = ARRAY['конфликт', 'земля', 'пентакли']::text[], keywords_en = ARRAY['conflict', 'earth', 'pentacles']::text[], description_ru = 'Карта «Пятёрка Пентаклей» отражает труда, денег и материального мира через призму темы «конфликт».', description_en = 'The five of the pentacles suit, carrying work, money, and the material world through the lens of conflict.', meaning_upright = 'Трения, соперничество или сбой, проверяющие на прочность сферу труда, денег и материального мира, — неприятно, но редко навсегда.', meaning_reversed = 'Конфликт в сфере труда, денег и материального мира начинает стихать, или урок из него наконец усваивается.', meaning_upright_en = 'Friction, competition, or disruption testing work, money, and the material world — uncomfortable, but rarely permanent.', meaning_reversed_en = 'Conflict in work, money, and the material world beginning to ease, or a lesson from it finally sinking in.', meanings_ru = '{"upright":"Трения, соперничество или сбой, проверяющие на прочность сферу труда, денег и материального мира, — неприятно, но редко навсегда.","reversed":"Конфликт в сфере труда, денег и материального мира начинает стихать, или урок из него наконец усваивается.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"Friction, competition, or disruption testing work, money, and the material world — uncomfortable, but rarely permanent.","reversed":"Conflict in work, money, and the material world beginning to ease, or a lesson from it finally sinking in.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'no' WHERE id = 69 AND num = 5;
UPDATE tarot_cards SET slug = 'six-of-pentacles', name_en = 'Six of Pentacles', keywords_ru = ARRAY['гармония', 'земля', 'пентакли']::text[], keywords_en = ARRAY['harmony', 'earth', 'pentacles']::text[], description_ru = 'Карта «Шестёрка Пентаклей» отражает труда, денег и материального мира через призму темы «гармония».', description_en = 'The six of the pentacles suit, carrying work, money, and the material world through the lens of harmony.', meaning_upright = 'Возвращение к равновесию и щедрости в сфере труда, денег и материального мира — сотрудничество работает в вашу пользу.', meaning_reversed = 'Старый дисбаланс в сфере труда, денег и материального мира снова всплывает, или щедрость остаётся без отклика.', meaning_upright_en = 'A return to balance and generosity within work, money, and the material world — cooperation working in your favor.', meaning_reversed_en = 'An old imbalance in work, money, and the material world resurfacing, or generosity that isn''t being returned.', meanings_ru = '{"upright":"Возвращение к равновесию и щедрости в сфере труда, денег и материального мира — сотрудничество работает в вашу пользу.","reversed":"Старый дисбаланс в сфере труда, денег и материального мира снова всплывает, или щедрость остаётся без отклика.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"A return to balance and generosity within work, money, and the material world — cooperation working in your favor.","reversed":"An old imbalance in work, money, and the material world resurfacing, or generosity that isn''t being returned.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'yes' WHERE id = 70 AND num = 6;
UPDATE tarot_cards SET slug = 'seven-of-pentacles', name_en = 'Seven of Pentacles', keywords_ru = ARRAY['размышление', 'земля', 'пентакли']::text[], keywords_en = ARRAY['reflection', 'earth', 'pentacles']::text[], description_ru = 'Карта «Семёрка Пентаклей» отражает труда, денег и материального мира через призму темы «размышление».', description_en = 'The seven of the pentacles suit, carrying work, money, and the material world through the lens of reflection.', meaning_upright = 'Момент оценить стратегию в сфере труда, денег и материального мира — настойчивость и честное размышление вместо быстрых действий.', meaning_reversed = 'Сомнения в себе или обходной путь в сфере труда, денег и материального мира, который, скорее всего, ещё напомнит о себе.', meaning_upright_en = 'A moment to assess strategy within work, money, and the material world — perseverance and honest reflection over quick action.', meaning_reversed_en = 'Second-guessing, or a shortcut within work, money, and the material world that''s likely to catch up with you.', meanings_ru = '{"upright":"Момент оценить стратегию в сфере труда, денег и материального мира — настойчивость и честное размышление вместо быстрых действий.","reversed":"Сомнения в себе или обходной путь в сфере труда, денег и материального мира, который, скорее всего, ещё напомнит о себе.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"A moment to assess strategy within work, money, and the material world — perseverance and honest reflection over quick action.","reversed":"Second-guessing, or a shortcut within work, money, and the material world that''s likely to catch up with you.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'maybe' WHERE id = 71 AND num = 7;
UPDATE tarot_cards SET slug = 'eight-of-pentacles', name_en = 'Eight of Pentacles', keywords_ru = ARRAY['импульс', 'земля', 'пентакли']::text[], keywords_en = ARRAY['momentum', 'earth', 'pentacles']::text[], description_ru = 'Карта «Восьмёрка Пентаклей» отражает труда, денег и материального мира через призму темы «импульс».', description_en = 'The eight of the pentacles suit, carrying work, money, and the material world through the lens of momentum.', meaning_upright = 'Сфокусированное мастерство и быстрый импульс в сфере труда, денег и материального мира — реальный прогресс благодаря отточенным усилиям.', meaning_reversed = 'Ощущение застоя, распылённости или самоограничения в сфере труда, денег и материального мира, несмотря на вложенные усилия.', meaning_upright_en = 'Focused skill and fast momentum within work, money, and the material world — real progress through practiced effort.', meaning_reversed_en = 'Feeling stuck, scattered, or self-limited within work, money, and the material world despite the effort going in.', meanings_ru = '{"upright":"Сфокусированное мастерство и быстрый импульс в сфере труда, денег и материального мира — реальный прогресс благодаря отточенным усилиям.","reversed":"Ощущение застоя, распылённости или самоограничения в сфере труда, денег и материального мира, несмотря на вложенные усилия.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"Focused skill and fast momentum within work, money, and the material world — real progress through practiced effort.","reversed":"Feeling stuck, scattered, or self-limited within work, money, and the material world despite the effort going in.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'yes-if-cautious' WHERE id = 72 AND num = 8;
UPDATE tarot_cards SET slug = 'nine-of-pentacles', name_en = 'Nine of Pentacles', keywords_ru = ARRAY['стойкость', 'земля', 'пентакли']::text[], keywords_en = ARRAY['resilience', 'earth', 'pentacles']::text[], description_ru = 'Карта «Девятка Пентаклей» отражает труда, денег и материального мира через призму темы «стойкость».', description_en = 'The nine of the pentacles suit, carrying work, money, and the material world through the lens of resilience.', meaning_upright = 'Стойкость у финишной черты в сфере труда, денег и материального мира — почти у цели, благодаря всему, что уже пережито.', meaning_reversed = 'Истощение, тревога или страх потери в сфере труда, денег и материального мира, превосходящие саму ситуацию.', meaning_upright_en = 'Resilience close to the finish line in work, money, and the material world — nearly there, on the strength of what''s already been endured.', meaning_reversed_en = 'Exhaustion, worry, or a fear of loss within work, money, and the material world that''s bigger than the situation itself.', meanings_ru = '{"upright":"Стойкость у финишной черты в сфере труда, денег и материального мира — почти у цели, благодаря всему, что уже пережито.","reversed":"Истощение, тревога или страх потери в сфере труда, денег и материального мира, превосходящие саму ситуацию.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"Resilience close to the finish line in work, money, and the material world — nearly there, on the strength of what''s already been endured.","reversed":"Exhaustion, worry, or a fear of loss within work, money, and the material world that''s bigger than the situation itself.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'maybe' WHERE id = 73 AND num = 9;
UPDATE tarot_cards SET slug = 'ten-of-pentacles', name_en = 'Ten of Pentacles', keywords_ru = ARRAY['завершение', 'земля', 'пентакли']::text[], keywords_en = ARRAY['completion', 'earth', 'pentacles']::text[], description_ru = 'Карта «Десятка Пентаклей» отражает труда, денег и материального мира через призму темы «завершение».', description_en = 'The ten of the pentacles suit, carrying work, money, and the material world through the lens of completion.', meaning_upright = 'Цикл в сфере труда, денег и материального мира подходит к естественному завершению — полному, будь то торжество или груз, который наконец можно снять.', meaning_reversed = 'Медленное, затянувшееся завершение в сфере труда, денег и материального мира или давление цикла, отказывающегося закрыться.', meaning_upright_en = 'A cycle of work, money, and the material world reaching its natural completion — full, whether that fullness feels like triumph or like a weight to finally set down.', meaning_reversed_en = 'A slow, drawn-out ending within work, money, and the material world, or the pressure of a cycle refusing to close.', meanings_ru = '{"upright":"Цикл в сфере труда, денег и материального мира подходит к естественному завершению — полному, будь то торжество или груз, который наконец можно снять.","reversed":"Медленное, затянувшееся завершение в сфере труда, денег и материального мира или давление цикла, отказывающегося закрыться.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"A cycle of work, money, and the material world reaching its natural completion — full, whether that fullness feels like triumph or like a weight to finally set down.","reversed":"A slow, drawn-out ending within work, money, and the material world, or the pressure of a cycle refusing to close.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'maybe' WHERE id = 74 AND num = 10;
UPDATE tarot_cards SET slug = 'page-of-pentacles', name_en = 'Page of Pentacles', keywords_ru = ARRAY['вестник', 'земля', 'пентакли']::text[], keywords_en = ARRAY['messenger', 'earth', 'pentacles']::text[], description_ru = 'Карта «Паж Пентаклей» воплощает архетип любознательного ученика в стихии труда, денег и материального мира.', description_en = 'A curious student within the pentacles suit, embodying work, money, and the material world.', meaning_upright = 'Любознательный ученик сферы труда, денег и материального мира — новость, урок или приглашение исследовать эту область свежим взглядом.', meaning_reversed = 'Незрелость, упущенное сообщение или небрежный подход к сфере труда, денег и материального мира.', meaning_upright_en = 'A curious student of work, money, and the material world — news, a lesson, or an invitation to explore this domain with fresh eyes.', meaning_reversed_en = 'Immaturity, a missed message, or work, money, and the material world approached carelessly.', meanings_ru = '{"upright":"Любознательный ученик сферы труда, денег и материального мира — новость, урок или приглашение исследовать эту область свежим взглядом.","reversed":"Незрелость, упущенное сообщение или небрежный подход к сфере труда, денег и материального мира.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"A curious student of work, money, and the material world — news, a lesson, or an invitation to explore this domain with fresh eyes.","reversed":"Immaturity, a missed message, or work, money, and the material world approached carelessly.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'maybe' WHERE id = 75 AND num = 11;
UPDATE tarot_cards SET slug = 'knight-of-pentacles', name_en = 'Knight of Pentacles', keywords_ru = ARRAY['стремление', 'земля', 'пентакли']::text[], keywords_en = ARRAY['pursuit', 'earth', 'pentacles']::text[], description_ru = 'Карта «Рыцарь Пентаклей» воплощает архетип энергичного искателя в стихии труда, денег и материального мира.', description_en = 'An energetic pursuer within the pentacles suit, embodying work, money, and the material world.', meaning_upright = 'Энергичное, целеустремлённое движение в сфере труда, денег и материального мира — действие и напор, к добру или к худу.', meaning_reversed = 'Безрассудство или погоня в сфере труда, денег и материального мира, ставшая импульсивной или хаотичной.', meaning_upright_en = 'Energetic, single-minded pursuit of work, money, and the material world — movement and action, for better or worse.', meaning_reversed_en = 'Recklessness, or pursuit of work, money, and the material world that has become impulsive or scattered.', meanings_ru = '{"upright":"Энергичное, целеустремлённое движение в сфере труда, денег и материального мира — действие и напор, к добру или к худу.","reversed":"Безрассудство или погоня в сфере труда, денег и материального мира, ставшая импульсивной или хаотичной.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"Energetic, single-minded pursuit of work, money, and the material world — movement and action, for better or worse.","reversed":"Recklessness, or pursuit of work, money, and the material world that has become impulsive or scattered.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'yes-if-cautious' WHERE id = 76 AND num = 12;
UPDATE tarot_cards SET slug = 'queen-of-pentacles', name_en = 'Queen of Pentacles', keywords_ru = ARRAY['интуитивное мастерство', 'земля', 'пентакли']::text[], keywords_en = ARRAY['intuitive mastery', 'earth', 'pentacles']::text[], description_ru = 'Карта «Королева Пентаклей» воплощает архетип интуитивного мастера в стихии труда, денег и материального мира.', description_en = 'An intuitive master within the pentacles suit, embodying work, money, and the material world.', meaning_upright = 'Интуитивное, глубоко усвоенное мастерство в сфере труда, денег и материального мира — забота об этой области из прожитого понимания, а не из теории.', meaning_reversed = 'Неуверенность или мастерство в сфере труда, денег и материального мира, обращённое внутрь и самокритичное вместо щедрого.', meaning_upright_en = 'Intuitive, internalized mastery of work, money, and the material world — nurturing this domain from lived understanding rather than theory.', meaning_reversed_en = 'Insecurity, or mastery of work, money, and the material world turned inward and self-critical instead of generous.', meanings_ru = '{"upright":"Интуитивное, глубоко усвоенное мастерство в сфере труда, денег и материального мира — забота об этой области из прожитого понимания, а не из теории.","reversed":"Неуверенность или мастерство в сфере труда, денег и материального мира, обращённое внутрь и самокритичное вместо щедрого.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"Intuitive, internalized mastery of work, money, and the material world — nurturing this domain from lived understanding rather than theory.","reversed":"Insecurity, or mastery of work, money, and the material world turned inward and self-critical instead of generous.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'yes' WHERE id = 77 AND num = 13;
UPDATE tarot_cards SET slug = 'king-of-pentacles', name_en = 'King of Pentacles', keywords_ru = ARRAY['власть', 'земля', 'пентакли']::text[], keywords_en = ARRAY['command', 'earth', 'pentacles']::text[], description_ru = 'Карта «Король Пентаклей» воплощает архетип властного правителя в стихии труда, денег и материального мира.', description_en = 'A commanding authority within the pentacles suit, embodying work, money, and the material world.', meaning_upright = 'Уверенное, внешне выраженное владение сферой труда, денег и материального мира — лидерство на основе опыта и заслуженного авторитета.', meaning_reversed = 'Проблемы с контролем или власть в сфере труда, денег и материального мира, применяемая жёстко, а не мудро.', meaning_upright_en = 'Confident, externalized command of work, money, and the material world — leading from experience and earned authority.', meaning_reversed_en = 'Control issues, or authority over work, money, and the material world used rigidly rather than wisely.', meanings_ru = '{"upright":"Уверенное, внешне выраженное владение сферой труда, денег и материального мира — лидерство на основе опыта и заслуженного авторитета.","reversed":"Проблемы с контролем или власть в сфере труда, денег и материального мира, применяемая жёстко, а не мудро.","love":"В делах сердца эта карта опирается на стабильность, обязательства и надёжную заботу — символически, сфера труда, денег и материального мира разворачивается между двумя людьми.","career":"На работе это указывает на устойчивый, ощутимый прогресс и мастерство.","finance":"В финансах это говорит о деньгах, ресурсах и долгосрочной безопасности.","spiritual":"В духовном плане одна из возможных трактовок связана с воплощением внутренних ценностей в повседневной, физической жизни."}'::jsonb, meanings_en = '{"upright":"Confident, externalized command of work, money, and the material world — leading from experience and earned authority.","reversed":"Control issues, or authority over work, money, and the material world used rigidly rather than wisely.","love":"In matters of the heart, this card leans on stability, commitment, and dependable care — symbolically, work, money, and the material world playing out between two people.","career":"At work, this points to steady, tangible progress and craftsmanship.","finance":"Financially, this suggests money, resources, and long-term security.","spiritual":"Spiritually, one possible interpretation centers on grounding inner values into daily, physical life."}'::jsonb, yes_no = 'yes' WHERE id = 78 AND num = 14;

-- Расклады: совпадающие с seed обновляются, остальные добавляются
UPDATE tarot_spreads SET slug = 'three-card', name_en = 'Three Card', description_en = 'Past, present, and future — the classic spread for a clear, narrative reading.', category = 'general', difficulty = 'beginner', position_details = '[{"id":"past","order":1,"label_ru":"Прошлое","label_en":"Past","meaning_ru":"Что привело вас сюда.","meaning_en":"What led you here."},{"id":"present","order":2,"label_ru":"Настоящее","label_en":"Present","meaning_ru":"Как обстоят дела прямо сейчас.","meaning_en":"Where things stand right now."},{"id":"future","order":3,"label_ru":"Будущее","label_en":"Future","meaning_ru":"К чему всё может привести.","meaning_en":"Where things may be heading."}]'::jsonb WHERE code = 'three_cards';
UPDATE tarot_spreads SET slug = 'yes-no', name_en = 'Yes / No', description_en = 'One card, read for its traditional yes-or-no leaning — best for a direct, simple question.', category = 'yes-no', difficulty = 'beginner', position_details = '[{"id":"answer","order":1,"label_ru":"Ответ","label_en":"Answer","meaning_ru":"Традиционная склонность карты в отношении вашего вопроса.","meaning_en":"The card''s traditional leaning on your question."}]'::jsonb WHERE code = 'yes_no';
UPDATE tarot_spreads SET slug = 'celtic-cross', name_en = 'Celtic Cross', description_en = 'The definitive ten-card deep dive — for when a question deserves real depth.', category = 'general', difficulty = 'advanced', position_details = '[{"id":"present","order":1,"label_ru":"Суть вопроса","label_en":"Heart of the Matter","meaning_ru":"Ядро ситуации.","meaning_en":"The core of the situation."},{"id":"challenge","order":2,"label_ru":"Непосредственное препятствие","label_en":"Immediate Challenge","meaning_ru":"Что противостоит вам прямо сейчас.","meaning_en":"What''s crossing you right now."},{"id":"foundation","order":3,"label_ru":"Основа","label_en":"Foundation","meaning_ru":"Далёкое прошлое, сформировавшее ситуацию.","meaning_en":"The deep, distant past shaping this."},{"id":"recentPast","order":4,"label_ru":"Недавнее прошлое","label_en":"Recent Past","meaning_ru":"Что только что произошло или уходит.","meaning_en":"What''s just happened or is passing."},{"id":"crown","order":5,"label_ru":"Лучший исход","label_en":"Best Outcome","meaning_ru":"Лучшая осознанная цель или исход, к которому стоит стремиться.","meaning_en":"The best conscious goal or outcome to aim for."},{"id":"nearFuture","order":6,"label_ru":"Ближайшее будущее","label_en":"Near Future","meaning_ru":"Что произойдёт дальше.","meaning_en":"What''s coming next."},{"id":"stance","order":7,"label_ru":"Ваша позиция","label_en":"Your Stance","meaning_ru":"Как вы подходите к ситуации.","meaning_en":"How you''re approaching this."},{"id":"external","order":8,"label_ru":"Внешние влияния","label_en":"External Influences","meaning_ru":"Люди и обстоятельства вокруг вас.","meaning_en":"People and circumstances around you."},{"id":"hopesFears","order":9,"label_ru":"Надежды и страхи","label_en":"Hopes & Fears","meaning_ru":"На что вы надеетесь — и чего боитесь.","meaning_en":"What you''re hoping for — and afraid of."},{"id":"outcome","order":10,"label_ru":"Итоговый результат","label_en":"Final Outcome","meaning_ru":"К чему всё придёт, если текущий путь сохранится.","meaning_en":"Where this is heading if the current path continues."}]'::jsonb WHERE code = 'celtic_cross';

