UPDATE zodiac_signs SET name_en = 'Scorpio', modality = 'fixed', ruling_planet = 'pluto', keywords_ru = ARRAY['интенсивность', 'трансформация', 'глубина']::text[], keywords_en = ARRAY['intensity', 'transformation', 'depth']::text[], description_ru = 'Знак воды, связанный с эмоциональной интенсивностью, трансформацией и умением смотреть туда, куда другие избегают смотреть.', description_en = 'A water sign associated with emotional intensity, transformation, and a comfort with what others avoid looking at.', strengths_ru = ARRAY['Страсть', 'Стойкость', 'Верность']::text[], strengths_en = ARRAY['Passion', 'Resilience', 'Loyalty']::text[], challenges_ru = ARRAY['Ревность', 'Скрытность', 'Трудности с доверием']::text[], challenges_en = ARRAY['Jealousy', 'Secretiveness', 'Difficulty trusting']::text[] WHERE code = 'scorpio';
