UPDATE zodiac_signs SET name_en = 'Pisces', modality = 'mutable', ruling_planet = 'neptune', keywords_ru = ARRAY['интуиция', 'эмпатия', 'воображение']::text[], keywords_en = ARRAY['intuition', 'empathy', 'imagination']::text[], description_ru = 'Знак воды, связанный с мечтами, состраданием и почти прозрачной границей между собой и всеми вокруг.', description_en = 'A water sign associated with dreams, compassion, and a porous boundary between itself and everyone around it.', strengths_ru = ARRAY['Сострадание', 'Творчество', 'Приспособляемость']::text[], strengths_en = ARRAY['Compassion', 'Creativity', 'Adaptability']::text[], challenges_ru = ARRAY['Эскапизм', 'Чрезмерный идеализм', 'Трудности с границами']::text[], challenges_en = ARRAY['Escapism', 'Over-idealism', 'Difficulty with boundaries']::text[] WHERE code = 'pisces';

-- Планеты, дома, аспекты, дневная/ночная карта

-- Города для выбора места рождения

-- Нумерология: число жизненного пути и остальные числа профиля

-- «На кого вы похожи»: знаменитости (знак зодиака считает триггер) и архетипы старших арканов

DO $$
DECLARE n integer;
BEGIN
    SELECT count(*) FROM tarot_cards WHERE slug IS NOT NULL AND name_en IS NOT NULL AND meaning_upright IS NOT NULL AND meaning_upright_en IS NOT NULL INTO n;
    IF n <> 78 THEN RAISE EXCEPTION 'content check failed: tarot_cards with slug: expected 78, got %', n; END IF;
    SELECT count(*) FROM tarot_spreads WHERE slug IS NOT NULL AND name_en IS NOT NULL AND jsonb_array_length(position_details) > 0 INTO n;
    IF n <> 7 THEN RAISE EXCEPTION 'content check failed: tarot_spreads with slug: expected 7, got %', n; END IF;
    SELECT count(*) FROM zodiac_signs WHERE name_en IS NOT NULL AND description_ru IS NOT NULL AND ruling_planet IS NOT NULL INTO n;
    IF n <> 12 THEN RAISE EXCEPTION 'content check failed: zodiac_signs filled: expected 12, got %', n; END IF;
    SELECT count(*) FROM numerology_meanings INTO n;
    IF n <> 72 THEN RAISE EXCEPTION 'content check failed: numerology_meanings: expected 72, got %', n; END IF;
    SELECT count(*) FROM planets INTO n;
    IF n <> 10 THEN RAISE EXCEPTION 'content check failed: planets: expected 10, got %', n; END IF;
    SELECT count(*) FROM houses INTO n;
    IF n <> 12 THEN RAISE EXCEPTION 'content check failed: houses: expected 12, got %', n; END IF;
    SELECT count(*) FROM aspects INTO n;
    IF n <> 5 THEN RAISE EXCEPTION 'content check failed: aspects: expected 5, got %', n; END IF;
    SELECT count(*) FROM sect_profiles INTO n;
    IF n <> 2 THEN RAISE EXCEPTION 'content check failed: sect_profiles: expected 2, got %', n; END IF;
    SELECT count(*) FROM cities INTO n;
    IF n <> 77 THEN RAISE EXCEPTION 'content check failed: cities: expected 77, got %', n; END IF;
    SELECT count(*) FROM celebrities WHERE zodiac_sign_id IS NOT NULL INTO n;
    IF n <> 20 THEN RAISE EXCEPTION 'content check failed: celebrities: expected 20, got %', n; END IF;
    SELECT count(*) FROM card_archetypes INTO n;
    IF n <> 44 THEN RAISE EXCEPTION 'content check failed: card_archetypes: expected 44, got %', n; END IF;
END
$$;

COMMIT;
