INSERT INTO tarot_spreads (code, slug, name_ru, name_en, description, description_en, cards_count, positions, position_details, category, difficulty, price, premium_only, sort_order) VALUES ('one_card', 'one-card', 'Одна карта', 'One Card', 'Одна карта для быстрого, сфокусированного ответа или ежедневной практики.', 'A single card for a quick, focused answer or a daily check-in.', 1, '["Фокус"]'::jsonb, '[{"id":"focus","order":1,"label_ru":"Фокус","label_en":"Focus","meaning_ru":"Самая значимая энергия для вашего вопроса прямо сейчас.","meaning_en":"The single most relevant energy for your question right now."}]'::jsonb, 'general', 'beginner', 0, false, 60) ON CONFLICT (code) DO UPDATE SET slug = EXCLUDED.slug, name_en = EXCLUDED.name_en, description_en = EXCLUDED.description_en, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, position_details = EXCLUDED.position_details;
INSERT INTO tarot_spreads (code, slug, name_ru, name_en, description, description_en, cards_count, positions, position_details, category, difficulty, price, premium_only, sort_order) VALUES ('five_card', 'five-card', 'Пять карт', 'Five Card', 'Более глубокий взгляд на ситуацию: что происходит, что мешает и что с этим делать.', 'A deeper look at a situation: what''s happening, what''s in the way, and what to do about it.', 5, '["Ситуация","Препятствие","Первопричина","Совет","Итог"]'::jsonb, '[{"id":"situation","order":1,"label_ru":"Ситуация","label_en":"Situation","meaning_ru":"Суть происходящего.","meaning_en":"The heart of what''s going on."},{"id":"challenge","order":2,"label_ru":"Препятствие","label_en":"Challenge","meaning_ru":"Что усложняет ситуацию.","meaning_en":"What''s making this harder."},{"id":"root","order":3,"label_ru":"Первопричина","label_en":"Root","meaning_ru":"Глубинная причина происходящего.","meaning_en":"The underlying cause."},{"id":"advice","order":4,"label_ru":"Совет","label_en":"Advice","meaning_ru":"Предлагаемый путь вперёд.","meaning_en":"A suggested way forward."},{"id":"outcome","order":5,"label_ru":"Итог","label_en":"Outcome","meaning_ru":"К чему это, вероятно, приведёт.","meaning_en":"Where this is likely heading."}]'::jsonb, 'general', 'intermediate', 0, false, 70) ON CONFLICT (code) DO UPDATE SET slug = EXCLUDED.slug, name_en = EXCLUDED.name_en, description_en = EXCLUDED.description_en, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, position_details = EXCLUDED.position_details;
INSERT INTO tarot_spreads (code, slug, name_ru, name_en, description, description_en, cards_count, positions, position_details, category, difficulty, price, premium_only, sort_order) VALUES ('love', 'love', 'Расклад на любовь', 'Love Spread', 'Расклад на пять карт о романтической связи — обе стороны, связь между вами и куда она может привести.', 'A five-card look at a romantic connection — both sides, the bond between you, and where it can go.', 5, '["Вы","Партнёр","Связь","Испытание","Потенциал"]'::jsonb, '[{"id":"you","order":1,"label_ru":"Вы","label_en":"You","meaning_ru":"Ваша энергия в этой связи.","meaning_en":"Your energy in this connection."},{"id":"partner","order":2,"label_ru":"Партнёр","label_en":"Partner","meaning_ru":"Энергия партнёра в этой связи.","meaning_en":"Their energy in this connection."},{"id":"connection","order":3,"label_ru":"Связь","label_en":"Connection","meaning_ru":"Что вас связывает.","meaning_en":"What binds you together."},{"id":"challenge","order":4,"label_ru":"Испытание","label_en":"Challenge","meaning_ru":"Что испытывает отношения на прочность.","meaning_en":"What''s testing the relationship."},{"id":"potential","order":5,"label_ru":"Потенциал","label_en":"Potential","meaning_ru":"Куда может привести эта связь.","meaning_en":"Where this connection could go."}]'::jsonb, 'love', 'intermediate', 0, true, 80) ON CONFLICT (code) DO UPDATE SET slug = EXCLUDED.slug, name_en = EXCLUDED.name_en, description_en = EXCLUDED.description_en, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, position_details = EXCLUDED.position_details;
INSERT INTO tarot_spreads (code, slug, name_ru, name_en, description, description_en, cards_count, positions, position_details, category, difficulty, price, premium_only, sort_order) VALUES ('career', 'career', 'Расклад на карьеру', 'Career Spread', 'Расклад на четыре карты о вашем профессиональном пути — ситуация, препятствие, действие и вероятный итог.', 'A four-card read on your professional path — situation, obstacle, action, and likely outcome.', 4, '["Текущая ситуация","Препятствие","Действие","Вероятный итог"]'::jsonb, '[{"id":"situation","order":1,"label_ru":"Текущая ситуация","label_en":"Current Situation","meaning_ru":"Как обстоят дела в профессиональном плане.","meaning_en":"Where things stand professionally."},{"id":"obstacle","order":2,"label_ru":"Препятствие","label_en":"Obstacle","meaning_ru":"Что стоит у вас на пути.","meaning_en":"What''s standing in your way."},{"id":"action","order":3,"label_ru":"Действие","label_en":"Action to Take","meaning_ru":"Предлагаемый следующий шаг.","meaning_en":"A suggested next move."},{"id":"outcome","order":4,"label_ru":"Вероятный итог","label_en":"Likely Outcome","meaning_ru":"К чему может привести этот путь.","meaning_en":"Where this path may lead."}]'::jsonb, 'career', 'intermediate', 0, true, 90) ON CONFLICT (code) DO UPDATE SET slug = EXCLUDED.slug, name_en = EXCLUDED.name_en, description_en = EXCLUDED.description_en, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, position_details = EXCLUDED.position_details;
