INSERT INTO aspects (type, angle_deg, orb_deg, symbol, label_ru, label_en, meaning_ru, meaning_en) VALUES ('conjunction', 0, 8, '☌', 'Соединение', 'Conjunction', 'эти две энергии сливаются в единую, трудно различимую силу', 'these two blend into a single, hard-to-separate force') ON CONFLICT (type) DO UPDATE SET angle_deg = EXCLUDED.angle_deg, orb_deg = EXCLUDED.orb_deg, symbol = EXCLUDED.symbol, label_ru = EXCLUDED.label_ru, label_en = EXCLUDED.label_en, meaning_ru = EXCLUDED.meaning_ru, meaning_en = EXCLUDED.meaning_en;
INSERT INTO aspects (type, angle_deg, orb_deg, symbol, label_ru, label_en, meaning_ru, meaning_en) VALUES ('sextile', 60, 5, '⚹', 'Секстиль', 'Sextile', 'эти энергии поддерживают друг друга, если приложить немного усилий', 'these support each other, given a little effort') ON CONFLICT (type) DO UPDATE SET angle_deg = EXCLUDED.angle_deg, orb_deg = EXCLUDED.orb_deg, symbol = EXCLUDED.symbol, label_ru = EXCLUDED.label_ru, label_en = EXCLUDED.label_en, meaning_ru = EXCLUDED.meaning_ru, meaning_en = EXCLUDED.meaning_en;
INSERT INTO aspects (type, angle_deg, orb_deg, symbol, label_ru, label_en, meaning_ru, meaning_en) VALUES ('square', 90, 7, '□', 'Квадрат', 'Square', 'эти энергии создают продуктивное трение — напряжение, с которым стоит работать', 'these create productive friction — a tension worth working with') ON CONFLICT (type) DO UPDATE SET angle_deg = EXCLUDED.angle_deg, orb_deg = EXCLUDED.orb_deg, symbol = EXCLUDED.symbol, label_ru = EXCLUDED.label_ru, label_en = EXCLUDED.label_en, meaning_ru = EXCLUDED.meaning_ru, meaning_en = EXCLUDED.meaning_en;
INSERT INTO aspects (type, angle_deg, orb_deg, symbol, label_ru, label_en, meaning_ru, meaning_en) VALUES ('trine', 120, 7, '△', 'Трин', 'Trine', 'эти энергии текут вместе легко — порой даже слишком легко', 'these flow together easily, almost too easily') ON CONFLICT (type) DO UPDATE SET angle_deg = EXCLUDED.angle_deg, orb_deg = EXCLUDED.orb_deg, symbol = EXCLUDED.symbol, label_ru = EXCLUDED.label_ru, label_en = EXCLUDED.label_en, meaning_ru = EXCLUDED.meaning_ru, meaning_en = EXCLUDED.meaning_en;
INSERT INTO aspects (type, angle_deg, orb_deg, symbol, label_ru, label_en, meaning_ru, meaning_en) VALUES ('opposition', 180, 8, '☍', 'Оппозиция', 'Opposition', 'эти энергии тянут в разные стороны и просят баланса', 'these pull in opposite directions, asking for balance') ON CONFLICT (type) DO UPDATE SET angle_deg = EXCLUDED.angle_deg, orb_deg = EXCLUDED.orb_deg, symbol = EXCLUDED.symbol, label_ru = EXCLUDED.label_ru, label_en = EXCLUDED.label_en, meaning_ru = EXCLUDED.meaning_ru, meaning_en = EXCLUDED.meaning_en;
INSERT INTO sect_profiles (id, title_ru, title_en, description_ru, description_en, favored_planets, keynote_ru, keynote_en) VALUES ('day', 'Дневная карта', 'Day Chart', 'Родились при Солнце над горизонтом. В древней эллинистической традиции дневная карта читается как более внешняя, деятельная и ориентированная на личность — тон задаёт собственный свет Солнца.', 'Born with the Sun above the horizon. In the old Hellenistic tradition, a day chart is read as more outward, active, and identity-driven — the Sun''s own light setting the tone.', ARRAY['sun', 'jupiter', 'saturn']::text[], 'Этот расклад может говорить, что ваша карта опирается на разум, структуру и видимое действие как на естественные сильные стороны.', 'This reading may suggest your chart leans on reason, structure, and visible action as natural strengths.') ON CONFLICT (id) DO UPDATE SET title_ru = EXCLUDED.title_ru, title_en = EXCLUDED.title_en, description_ru = EXCLUDED.description_ru, description_en = EXCLUDED.description_en, favored_planets = EXCLUDED.favored_planets, keynote_ru = EXCLUDED.keynote_ru, keynote_en = EXCLUDED.keynote_en;
INSERT INTO sect_profiles (id, title_ru, title_en, description_ru, description_en, favored_planets, keynote_ru, keynote_en) VALUES ('night', 'Ночная карта', 'Night Chart', 'Родились при Солнце под горизонтом. Ночная карта традиционно читается как более внутренняя, эмоциональная и инстинктивная — тон задаёт отражённый свет Луны.', 'Born with the Sun below the horizon. A night chart is traditionally read as more inward, emotional, and instinct-driven — the Moon''s reflected light setting the tone instead.', ARRAY['moon', 'venus', 'mars']::text[], 'Этот расклад может говорить, что ваша карта опирается на интуицию, чувства и инстинкт как на естественные сильные стороны.', 'This reading may suggest your chart leans on intuition, feeling, and instinct as natural strengths.') ON CONFLICT (id) DO UPDATE SET title_ru = EXCLUDED.title_ru, title_en = EXCLUDED.title_en, description_ru = EXCLUDED.description_ru, description_en = EXCLUDED.description_en, favored_planets = EXCLUDED.favored_planets, keynote_ru = EXCLUDED.keynote_ru, keynote_en = EXCLUDED.keynote_en;
