INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 1, 'Лидер', 'Это может говорить о жизни, построенной на начинаниях — новых путях, новых идеях, новой почве. Независимость, как правило, важнее, чем вписаться в общее.', 'The Leader', 'This may suggest a life shaped by starting things — new paths, new ideas, new ground. Independence tends to matter more than fitting in.', ARRAY['независимость', 'инициатива', 'оригинальность']::text[], ARRAY['independence', 'initiative', 'originality']::text[], ARRAY['Природное лидерство', 'Смелость идти первым', 'Самостоятельность']::text[], ARRAY['Natural leadership', 'Courage to go first', 'Self-reliance']::text[], ARRAY['Упрямство', 'Нетерпение к чужому темпу', 'Склонность к изоляции']::text[], ARRAY['Stubbornness', 'Impatience with others'' pace', 'A tendency toward isolation']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('birthday', 1, 'Число дня рождения 1: Лидер', 'Природный дар, который проходит через всю вашу жизнь: «независимость» и «инициатива» — в духе архетипа «Лидер».', 'Birthday Number 1: The Leader', 'A natural gift running through your life: independence and initiative, in the spirit of Leader.', ARRAY['независимость', 'инициатива', 'оригинальность']::text[], ARRAY['independence', 'initiative', 'originality']::text[], ARRAY['Природное лидерство', 'Смелость идти первым', 'Самостоятельность']::text[], ARRAY['Natural leadership', 'Courage to go first', 'Self-reliance']::text[], ARRAY['Упрямство', 'Нетерпение к чужому темпу', 'Склонность к изоляции']::text[], ARRAY['Stubbornness', 'Impatience with others'' pace', 'A tendency toward isolation']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('destiny', 1, 'Число выражения 1: Лидер', 'Возможно, вы здесь, чтобы нести в мир темы «независимость» и «инициатива» — энергия архетипа «Лидер» проявляется в том, что вы делаете.', 'Expression Number 1: The Leader', 'This may suggest you''re here to bring independence and initiative into the world — the energy of Leader showing up in what you do.', ARRAY['независимость', 'инициатива', 'оригинальность']::text[], ARRAY['independence', 'initiative', 'originality']::text[], ARRAY['Природное лидерство', 'Смелость идти первым', 'Самостоятельность']::text[], ARRAY['Natural leadership', 'Courage to go first', 'Self-reliance']::text[], ARRAY['Упрямство', 'Нетерпение к чужому темпу', 'Склонность к изоляции']::text[], ARRAY['Stubbornness', 'Impatience with others'' pace', 'A tendency toward isolation']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('soul', 1, 'Число души 1: Лидер', 'В глубине души вас тянет к темам «независимость» и «инициатива» — это внутренняя мотивация архетипа «Лидер».', 'Soul Urge Number 1: The Leader', 'Underneath it all, there''s a pull toward independence and initiative — the inward motivation of Leader.', ARRAY['независимость', 'инициатива', 'оригинальность']::text[], ARRAY['independence', 'initiative', 'originality']::text[], ARRAY['Природное лидерство', 'Смелость идти первым', 'Самостоятельность']::text[], ARRAY['Natural leadership', 'Courage to go first', 'Self-reliance']::text[], ARRAY['Упрямство', 'Нетерпение к чужому темпу', 'Склонность к изоляции']::text[], ARRAY['Stubbornness', 'Impatience with others'' pace', 'A tendency toward isolation']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('personality', 1, 'Число личности 1: Лидер', 'С первого взгляда окружающие, скорее всего, видят в вас архетип «Лидер» — «независимость», «инициатива» — ещё до того, как узнают вас глубже.', 'Personality Number 1: The Leader', 'On first impression, people likely read Leader in you — independence, initiative — before they know you any deeper.', ARRAY['независимость', 'инициатива', 'оригинальность']::text[], ARRAY['independence', 'initiative', 'originality']::text[], ARRAY['Природное лидерство', 'Смелость идти первым', 'Самостоятельность']::text[], ARRAY['Natural leadership', 'Courage to go first', 'Self-reliance']::text[], ARRAY['Упрямство', 'Нетерпение к чужому темпу', 'Склонность к изоляции']::text[], ARRAY['Stubbornness', 'Impatience with others'' pace', 'A tendency toward isolation']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('maturity', 1, 'Число зрелости 1: Лидер', 'Позже в жизни этот расклад может указывать на постепенное вхождение в архетип «Лидер» — темы «независимость» и «инициатива» проявляются всё отчётливее.', 'Maturity Number 1: The Leader', 'Later in life, this reading may suggest a settling into Leader — independence and initiative coming more fully into focus.', ARRAY['независимость', 'инициатива', 'оригинальность']::text[], ARRAY['independence', 'initiative', 'originality']::text[], ARRAY['Природное лидерство', 'Смелость идти первым', 'Самостоятельность']::text[], ARRAY['Natural leadership', 'Courage to go first', 'Self-reliance']::text[], ARRAY['Упрямство', 'Нетерпение к чужому темпу', 'Склонность к изоляции']::text[], ARRAY['Stubbornness', 'Impatience with others'' pace', 'A tendency toward isolation']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 2, 'Дипломат', 'Одна из возможных трактовок — жизнь, выстроенная вокруг связей: считывать атмосферу, снимать напряжение, строить мосты между людьми.', 'The Diplomat', 'One possible interpretation is a life oriented around connection — reading a room, easing tension, building bridges between people.', ARRAY['партнёрство', 'гармония', 'чувствительность']::text[], ARRAY['partnership', 'harmony', 'sensitivity']::text[], ARRAY['Глубокая интуиция', 'Искреннее сотрудничество', 'Терпение']::text[], ARRAY['Deep intuition', 'Genuine cooperation', 'Patience']::text[], ARRAY['Нерешительность', 'Чрезмерная зависимость от чужого одобрения', 'Уход от необходимых конфликтов']::text[], ARRAY['Indecision', 'Over-relying on others'' approval', 'Avoiding necessary conflict']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('birthday', 2, 'Число дня рождения 2: Дипломат', 'Природный дар, который проходит через всю вашу жизнь: «партнёрство» и «гармония» — в духе архетипа «Дипломат».', 'Birthday Number 2: The Diplomat', 'A natural gift running through your life: partnership and harmony, in the spirit of Diplomat.', ARRAY['партнёрство', 'гармония', 'чувствительность']::text[], ARRAY['partnership', 'harmony', 'sensitivity']::text[], ARRAY['Глубокая интуиция', 'Искреннее сотрудничество', 'Терпение']::text[], ARRAY['Deep intuition', 'Genuine cooperation', 'Patience']::text[], ARRAY['Нерешительность', 'Чрезмерная зависимость от чужого одобрения', 'Уход от необходимых конфликтов']::text[], ARRAY['Indecision', 'Over-relying on others'' approval', 'Avoiding necessary conflict']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('destiny', 2, 'Число выражения 2: Дипломат', 'Возможно, вы здесь, чтобы нести в мир темы «партнёрство» и «гармония» — энергия архетипа «Дипломат» проявляется в том, что вы делаете.', 'Expression Number 2: The Diplomat', 'This may suggest you''re here to bring partnership and harmony into the world — the energy of Diplomat showing up in what you do.', ARRAY['партнёрство', 'гармония', 'чувствительность']::text[], ARRAY['partnership', 'harmony', 'sensitivity']::text[], ARRAY['Глубокая интуиция', 'Искреннее сотрудничество', 'Терпение']::text[], ARRAY['Deep intuition', 'Genuine cooperation', 'Patience']::text[], ARRAY['Нерешительность', 'Чрезмерная зависимость от чужого одобрения', 'Уход от необходимых конфликтов']::text[], ARRAY['Indecision', 'Over-relying on others'' approval', 'Avoiding necessary conflict']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('soul', 2, 'Число души 2: Дипломат', 'В глубине души вас тянет к темам «партнёрство» и «гармония» — это внутренняя мотивация архетипа «Дипломат».', 'Soul Urge Number 2: The Diplomat', 'Underneath it all, there''s a pull toward partnership and harmony — the inward motivation of Diplomat.', ARRAY['партнёрство', 'гармония', 'чувствительность']::text[], ARRAY['partnership', 'harmony', 'sensitivity']::text[], ARRAY['Глубокая интуиция', 'Искреннее сотрудничество', 'Терпение']::text[], ARRAY['Deep intuition', 'Genuine cooperation', 'Patience']::text[], ARRAY['Нерешительность', 'Чрезмерная зависимость от чужого одобрения', 'Уход от необходимых конфликтов']::text[], ARRAY['Indecision', 'Over-relying on others'' approval', 'Avoiding necessary conflict']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('personality', 2, 'Число личности 2: Дипломат', 'С первого взгляда окружающие, скорее всего, видят в вас архетип «Дипломат» — «партнёрство», «гармония» — ещё до того, как узнают вас глубже.', 'Personality Number 2: The Diplomat', 'On first impression, people likely read Diplomat in you — partnership, harmony — before they know you any deeper.', ARRAY['партнёрство', 'гармония', 'чувствительность']::text[], ARRAY['partnership', 'harmony', 'sensitivity']::text[], ARRAY['Глубокая интуиция', 'Искреннее сотрудничество', 'Терпение']::text[], ARRAY['Deep intuition', 'Genuine cooperation', 'Patience']::text[], ARRAY['Нерешительность', 'Чрезмерная зависимость от чужого одобрения', 'Уход от необходимых конфликтов']::text[], ARRAY['Indecision', 'Over-relying on others'' approval', 'Avoiding necessary conflict']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('maturity', 2, 'Число зрелости 2: Дипломат', 'Позже в жизни этот расклад может указывать на постепенное вхождение в архетип «Дипломат» — темы «партнёрство» и «гармония» проявляются всё отчётливее.', 'Maturity Number 2: The Diplomat', 'Later in life, this reading may suggest a settling into Diplomat — partnership and harmony coming more fully into focus.', ARRAY['партнёрство', 'гармония', 'чувствительность']::text[], ARRAY['partnership', 'harmony', 'sensitivity']::text[], ARRAY['Глубокая интуиция', 'Искреннее сотрудничество', 'Терпение']::text[], ARRAY['Deep intuition', 'Genuine cooperation', 'Patience']::text[], ARRAY['Нерешительность', 'Чрезмерная зависимость от чужого одобрения', 'Уход от необходимых конфликтов']::text[], ARRAY['Indecision', 'Over-relying on others'' approval', 'Avoiding necessary conflict']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 3, 'Коммуникатор', 'Это может указывать на жизнь, находящую смысл в самовыражении — слове, искусстве, выступлении или просто умении озарить комнату.', 'The Communicator', 'This can point to a life that finds meaning through self-expression — words, art, performance, or simply lighting up a room.', ARRAY['самовыражение', 'творчество', 'радость']::text[], ARRAY['expression', 'creativity', 'joy']::text[], ARRAY['Харизма', 'Художественное чутьё', 'Оптимизм']::text[], ARRAY['Charisma', 'Artistic instinct', 'Optimism']::text[], ARRAY['Рассеянность внимания', 'Поверхностность под давлением', 'Перепады настроения']::text[], ARRAY['Scattered focus', 'Surface-level engagement under pressure', 'Mood swings']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
