INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 4, 'Строитель', 'Символически это указывает на жизнь, выстроенную кирпичик за кирпичиком — ровные усилия, надёжные системы и результаты, которые остаются.', 'The Builder', 'Symbolically, this points toward a life built brick by brick — steady effort, reliable systems, and results that last.', ARRAY['стабильность', 'дисциплина', 'структура']::text[], ARRAY['stability', 'discipline', 'structure']::text[], ARRAY['Надёжность', 'Организованность', 'Практичность в доведении дел до конца']::text[], ARRAY['Reliability', 'Organization', 'Practical follow-through']::text[], ARRAY['Жёсткость', 'Сопротивление переменам', 'Переработки до выгорания']::text[], ARRAY['Rigidity', 'Resistance to change', 'Overworking to the point of burnout']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
