INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('maturity', 4, 'Число зрелости 4: Строитель', 'Позже в жизни этот расклад может указывать на постепенное вхождение в архетип «Строитель» — темы «стабильность» и «дисциплина» проявляются всё отчётливее.', 'Maturity Number 4: The Builder', 'Later in life, this reading may suggest a settling into Builder — stability and discipline coming more fully into focus.', ARRAY['стабильность', 'дисциплина', 'структура']::text[], ARRAY['stability', 'discipline', 'structure']::text[], ARRAY['Надёжность', 'Организованность', 'Практичность в доведении дел до конца']::text[], ARRAY['Reliability', 'Organization', 'Practical follow-through']::text[], ARRAY['Жёсткость', 'Сопротивление переменам', 'Переработки до выгорания']::text[], ARRAY['Rigidity', 'Resistance to change', 'Overworking to the point of burnout']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 5, 'Свободный дух', 'Это может говорить о жизни, которая не терпит долгого стояния на месте: её тянет к новому опыту, новым местам, новым версиям себя.', 'The Free Spirit', 'This may suggest a life that resists staying still for long — drawn to new experiences, new places, new versions of itself.', ARRAY['перемены', 'приключения', 'свобода']::text[], ARRAY['change', 'adventure', 'freedom']::text[], ARRAY['Приспособляемость', 'Любопытство', 'Природное обаяние']::text[], ARRAY['Adaptability', 'Curiosity', 'Natural charm']::text[], ARRAY['Беспокойство', 'Импульсивные решения', 'Трудности с обязательствами']::text[], ARRAY['Restlessness', 'Impulsive decisions', 'Difficulty committing']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('birthday', 5, 'Число дня рождения 5: Свободный дух', 'Природный дар, который проходит через всю вашу жизнь: «перемены» и «приключения» — в духе архетипа «Свободный дух».', 'Birthday Number 5: The Free Spirit', 'A natural gift running through your life: change and adventure, in the spirit of Free Spirit.', ARRAY['перемены', 'приключения', 'свобода']::text[], ARRAY['change', 'adventure', 'freedom']::text[], ARRAY['Приспособляемость', 'Любопытство', 'Природное обаяние']::text[], ARRAY['Adaptability', 'Curiosity', 'Natural charm']::text[], ARRAY['Беспокойство', 'Импульсивные решения', 'Трудности с обязательствами']::text[], ARRAY['Restlessness', 'Impulsive decisions', 'Difficulty committing']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('destiny', 5, 'Число выражения 5: Свободный дух', 'Возможно, вы здесь, чтобы нести в мир темы «перемены» и «приключения» — энергия архетипа «Свободный дух» проявляется в том, что вы делаете.', 'Expression Number 5: The Free Spirit', 'This may suggest you''re here to bring change and adventure into the world — the energy of Free Spirit showing up in what you do.', ARRAY['перемены', 'приключения', 'свобода']::text[], ARRAY['change', 'adventure', 'freedom']::text[], ARRAY['Приспособляемость', 'Любопытство', 'Природное обаяние']::text[], ARRAY['Adaptability', 'Curiosity', 'Natural charm']::text[], ARRAY['Беспокойство', 'Импульсивные решения', 'Трудности с обязательствами']::text[], ARRAY['Restlessness', 'Impulsive decisions', 'Difficulty committing']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
