INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 6, 'Заботливый', 'Одна из возможных трактовок — жизнь, сосредоточенная на заботе: о семье, сообществе или о том, что требует внимания ближе всего к дому.', 'The Nurturer', 'One possible interpretation is a life centered on caretaking — of family, community, or whatever needs tending closest to home.', ARRAY['ответственность', 'забота', 'гармония']::text[], ARRAY['responsibility', 'care', 'harmony']::text[], ARRAY['Сострадание', 'Верность', 'Дар создавать гармонию']::text[], ARRAY['Compassion', 'Loyalty', 'A gift for creating harmony']::text[], ARRAY['Чрезмерное самопожертвование', 'Склонность к контролю', 'Перфекционизм']::text[], ARRAY['Self-sacrifice taken too far', 'Controlling tendencies', 'Perfectionism']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
