INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 7, 'Искатель', 'Это может указывать на жизнь, обращённую внутрь: вопросы, анализ и поиск того, что истинно под поверхностью.', 'The Seeker', 'This can point to a life oriented inward — questioning, analyzing, and looking for what''s true beneath the surface.', ARRAY['самоанализ', 'мудрость', 'глубина']::text[], ARRAY['introspection', 'wisdom', 'depth']::text[], ARRAY['Аналитическая глубина', 'Интуиция', 'Комфорт в одиночестве']::text[], ARRAY['Analytical depth', 'Intuition', 'Comfort with solitude']::text[], ARRAY['Изоляция', 'Избыточные размышления', 'Скептицизм, закрывающий путь к близости']::text[], ARRAY['Isolation', 'Overthinking', 'Skepticism that shuts out connection']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('birthday', 7, 'Число дня рождения 7: Искатель', 'Природный дар, который проходит через всю вашу жизнь: «самоанализ» и «мудрость» — в духе архетипа «Искатель».', 'Birthday Number 7: The Seeker', 'A natural gift running through your life: introspection and wisdom, in the spirit of Seeker.', ARRAY['самоанализ', 'мудрость', 'глубина']::text[], ARRAY['introspection', 'wisdom', 'depth']::text[], ARRAY['Аналитическая глубина', 'Интуиция', 'Комфорт в одиночестве']::text[], ARRAY['Analytical depth', 'Intuition', 'Comfort with solitude']::text[], ARRAY['Изоляция', 'Избыточные размышления', 'Скептицизм, закрывающий путь к близости']::text[], ARRAY['Isolation', 'Overthinking', 'Skepticism that shuts out connection']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('destiny', 7, 'Число выражения 7: Искатель', 'Возможно, вы здесь, чтобы нести в мир темы «самоанализ» и «мудрость» — энергия архетипа «Искатель» проявляется в том, что вы делаете.', 'Expression Number 7: The Seeker', 'This may suggest you''re here to bring introspection and wisdom into the world — the energy of Seeker showing up in what you do.', ARRAY['самоанализ', 'мудрость', 'глубина']::text[], ARRAY['introspection', 'wisdom', 'depth']::text[], ARRAY['Аналитическая глубина', 'Интуиция', 'Комфорт в одиночестве']::text[], ARRAY['Analytical depth', 'Intuition', 'Comfort with solitude']::text[], ARRAY['Изоляция', 'Избыточные размышления', 'Скептицизм, закрывающий путь к близости']::text[], ARRAY['Isolation', 'Overthinking', 'Skepticism that shuts out connection']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('soul', 7, 'Число души 7: Искатель', 'В глубине души вас тянет к темам «самоанализ» и «мудрость» — это внутренняя мотивация архетипа «Искатель».', 'Soul Urge Number 7: The Seeker', 'Underneath it all, there''s a pull toward introspection and wisdom — the inward motivation of Seeker.', ARRAY['самоанализ', 'мудрость', 'глубина']::text[], ARRAY['introspection', 'wisdom', 'depth']::text[], ARRAY['Аналитическая глубина', 'Интуиция', 'Комфорт в одиночестве']::text[], ARRAY['Analytical depth', 'Intuition', 'Comfort with solitude']::text[], ARRAY['Изоляция', 'Избыточные размышления', 'Скептицизм, закрывающий путь к близости']::text[], ARRAY['Isolation', 'Overthinking', 'Skepticism that shuts out connection']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('personality', 7, 'Число личности 7: Искатель', 'С первого взгляда окружающие, скорее всего, видят в вас архетип «Искатель» — «самоанализ», «мудрость» — ещё до того, как узнают вас глубже.', 'Personality Number 7: The Seeker', 'On first impression, people likely read Seeker in you — introspection, wisdom — before they know you any deeper.', ARRAY['самоанализ', 'мудрость', 'глубина']::text[], ARRAY['introspection', 'wisdom', 'depth']::text[], ARRAY['Аналитическая глубина', 'Интуиция', 'Комфорт в одиночестве']::text[], ARRAY['Analytical depth', 'Intuition', 'Comfort with solitude']::text[], ARRAY['Изоляция', 'Избыточные размышления', 'Скептицизм, закрывающий путь к близости']::text[], ARRAY['Isolation', 'Overthinking', 'Skepticism that shuts out connection']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
