INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 9, 'Гуманист', 'Это может говорить о жизни, обращённой к отдаче: щедрой, идеалистичной, часто более комфортной в роли помогающего, чем принимающего помощь.', 'The Humanitarian', 'This may suggest a life oriented toward giving — generous, idealistic, and often more comfortable helping than being helped.', ARRAY['сострадание', 'идеализм', 'завершённость']::text[], ARRAY['compassion', 'idealism', 'completion']::text[], ARRAY['Щедрость', 'Широкая эмпатия', 'Заслуженная мудрость']::text[], ARRAY['Generosity', 'Broad empathy', 'Hard-won wisdom']::text[], ARRAY['Мученичество', 'Трудности с отпусканием', 'Эмоциональная перегрузка']::text[], ARRAY['Martyrdom', 'Difficulty letting go', 'Emotional overwhelm']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
