INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('soul', 9, 'Число души 9: Гуманист', 'В глубине души вас тянет к темам «сострадание» и «идеализм» — это внутренняя мотивация архетипа «Гуманист».', 'Soul Urge Number 9: The Humanitarian', 'Underneath it all, there''s a pull toward compassion and idealism — the inward motivation of Humanitarian.', ARRAY['сострадание', 'идеализм', 'завершённость']::text[], ARRAY['compassion', 'idealism', 'completion']::text[], ARRAY['Щедрость', 'Широкая эмпатия', 'Заслуженная мудрость']::text[], ARRAY['Generosity', 'Broad empathy', 'Hard-won wisdom']::text[], ARRAY['Мученичество', 'Трудности с отпусканием', 'Эмоциональная перегрузка']::text[], ARRAY['Martyrdom', 'Difficulty letting go', 'Emotional overwhelm']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('personality', 9, 'Число личности 9: Гуманист', 'С первого взгляда окружающие, скорее всего, видят в вас архетип «Гуманист» — «сострадание», «идеализм» — ещё до того, как узнают вас глубже.', 'Personality Number 9: The Humanitarian', 'On first impression, people likely read Humanitarian in you — compassion, idealism — before they know you any deeper.', ARRAY['сострадание', 'идеализм', 'завершённость']::text[], ARRAY['compassion', 'idealism', 'completion']::text[], ARRAY['Щедрость', 'Широкая эмпатия', 'Заслуженная мудрость']::text[], ARRAY['Generosity', 'Broad empathy', 'Hard-won wisdom']::text[], ARRAY['Мученичество', 'Трудности с отпусканием', 'Эмоциональная перегрузка']::text[], ARRAY['Martyrdom', 'Difficulty letting go', 'Emotional overwhelm']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('maturity', 9, 'Число зрелости 9: Гуманист', 'Позже в жизни этот расклад может указывать на постепенное вхождение в архетип «Гуманист» — темы «сострадание» и «идеализм» проявляются всё отчётливее.', 'Maturity Number 9: The Humanitarian', 'Later in life, this reading may suggest a settling into Humanitarian — compassion and idealism coming more fully into focus.', ARRAY['сострадание', 'идеализм', 'завершённость']::text[], ARRAY['compassion', 'idealism', 'completion']::text[], ARRAY['Щедрость', 'Широкая эмпатия', 'Заслуженная мудрость']::text[], ARRAY['Generosity', 'Broad empathy', 'Hard-won wisdom']::text[], ARRAY['Мученичество', 'Трудности с отпусканием', 'Эмоциональная перегрузка']::text[], ARRAY['Martyrdom', 'Difficulty letting go', 'Emotional overwhelm']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 11, 'Интуит', 'Мастер-число — традиционно читается как усиленная чувствительность двойки. Это может указывать на жизнь, ведомую сильной интуицией и способностью вдохновлять других, нередко ценой личных затрат.', 'The Intuitive', 'A master number — traditionally read as an amplified version of 2''s sensitivity. This can point to a life carried by strong intuition and the ability to inspire others, often at some personal cost.', ARRAY['вдохновение', 'чувствительность', 'озарение']::text[], ARRAY['inspiration', 'sensitivity', 'insight']::text[], ARRAY['Видение', 'Обострённая чувствительность', 'Вдохновляющее присутствие']::text[], ARRAY['Visionary thinking', 'Heightened sensitivity', 'Inspiring presence']::text[], ARRAY['Нервное напряжение', 'Сомнения в себе', 'Ощущение перегрузки от собственного восприятия']::text[], ARRAY['Nervous energy', 'Self-doubt', 'Feeling overwhelmed by one''s own perception']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
