INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 22, 'Мастер-строитель', 'Мастер-число — традиционно читается как дисциплина четвёрки в большем масштабе. Это может говорить о жизни, способной превращать масштабные абстрактные замыслы в нечто конкретное и долговечное.', 'The Master Builder', 'A master number — traditionally read as 4''s discipline scaled up. This may suggest a life capable of turning big, abstract visions into something concrete and lasting.', ARRAY['видение', 'достижения', 'наследие']::text[], ARRAY['vision', 'achievement', 'legacy']::text[], ARRAY['Масштабное видение в сочетании с практическим исполнением', 'Природное лидерство', 'Прочное наследие']::text[], ARRAY['Large-scale vision paired with practical execution', 'Natural leadership', 'Enduring legacy']::text[], ARRAY['Огромное самозаданное давление', 'Сомнения в себе на высоком уровне', 'Выгорание']::text[], ARRAY['Enormous self-imposed pressure', 'Self-doubt at a high level', 'Burnout']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
