INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('maturity', 22, 'Число зрелости 22: Мастер-строитель', 'Позже в жизни этот расклад может указывать на постепенное вхождение в архетип «Мастер-строитель» — темы «видение» и «достижения» проявляются всё отчётливее.', 'Maturity Number 22: The Master Builder', 'Later in life, this reading may suggest a settling into Master Builder — vision and achievement coming more fully into focus.', ARRAY['видение', 'достижения', 'наследие']::text[], ARRAY['vision', 'achievement', 'legacy']::text[], ARRAY['Масштабное видение в сочетании с практическим исполнением', 'Природное лидерство', 'Прочное наследие']::text[], ARRAY['Large-scale vision paired with practical execution', 'Natural leadership', 'Enduring legacy']::text[], ARRAY['Огромное самозаданное давление', 'Сомнения в себе на высоком уровне', 'Выгорание']::text[], ARRAY['Enormous self-imposed pressure', 'Self-doubt at a high level', 'Burnout']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('life_path', 33, 'Мастер-учитель', 'Мастер-число — традиционно читается как забота шестёрки в большем масштабе. Это может указывать на жизнь, посвящённую исцелению и обучению на широком уровне, нередко с приоритетом чужого благополучия.', 'The Master Teacher', 'A master number — traditionally read as 6''s care scaled up. This can point to a life oriented around healing and teaching on a wide scale, often putting others'' wellbeing first.', ARRAY['сострадание', 'исцеление', 'служение']::text[], ARRAY['compassion', 'healing', 'service']::text[], ARRAY['Глубокая эмоциональная мудрость', 'Забота в большом масштабе', 'Бескорыстное служение']::text[], ARRAY['Deep emotional wisdom', 'Nurturing on a grand scale', 'Selfless service']::text[], ARRAY['Пренебрежение собой', 'Нереалистично высокие стандарты', 'Выгорание от чрезмерной отдачи']::text[], ARRAY['Self-neglect', 'Unrealistically high standards', 'Burnout from over-giving']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('birthday', 33, 'Число дня рождения 33: Мастер-учитель', 'Природный дар, который проходит через всю вашу жизнь: «сострадание» и «исцеление» — в духе архетипа «Мастер-учитель».', 'Birthday Number 33: The Master Teacher', 'A natural gift running through your life: compassion and healing, in the spirit of Master Teacher.', ARRAY['сострадание', 'исцеление', 'служение']::text[], ARRAY['compassion', 'healing', 'service']::text[], ARRAY['Глубокая эмоциональная мудрость', 'Забота в большом масштабе', 'Бескорыстное служение']::text[], ARRAY['Deep emotional wisdom', 'Nurturing on a grand scale', 'Selfless service']::text[], ARRAY['Пренебрежение собой', 'Нереалистично высокие стандарты', 'Выгорание от чрезмерной отдачи']::text[], ARRAY['Self-neglect', 'Unrealistically high standards', 'Burnout from over-giving']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
INSERT INTO numerology_meanings (kind, number, title, body, title_en, body_en, keywords_ru, keywords_en, strengths_ru, strengths_en, challenges_ru, challenges_en) VALUES ('destiny', 33, 'Число выражения 33: Мастер-учитель', 'Возможно, вы здесь, чтобы нести в мир темы «сострадание» и «исцеление» — энергия архетипа «Мастер-учитель» проявляется в том, что вы делаете.', 'Expression Number 33: The Master Teacher', 'This may suggest you''re here to bring compassion and healing into the world — the energy of Master Teacher showing up in what you do.', ARRAY['сострадание', 'исцеление', 'служение']::text[], ARRAY['compassion', 'healing', 'service']::text[], ARRAY['Глубокая эмоциональная мудрость', 'Забота в большом масштабе', 'Бескорыстное служение']::text[], ARRAY['Deep emotional wisdom', 'Nurturing on a grand scale', 'Selfless service']::text[], ARRAY['Пренебрежение собой', 'Нереалистично высокие стандарты', 'Выгорание от чрезмерной отдачи']::text[], ARRAY['Self-neglect', 'Unrealistically high standards', 'Burnout from over-giving']::text[]) ON CONFLICT (kind, number) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, title_en = EXCLUDED.title_en, body_en = EXCLUDED.body_en, keywords_ru = EXCLUDED.keywords_ru, keywords_en = EXCLUDED.keywords_en, strengths_ru = EXCLUDED.strengths_ru, strengths_en = EXCLUDED.strengths_en, challenges_ru = EXCLUDED.challenges_ru, challenges_en = EXCLUDED.challenges_en;
